# Round 54 -- part28 rows 150-185; 35 items
BATCH={
  (28, 150): {
   "topic": "lsilNextStep",
   "lead": "\u06af\u0627\u0645 \u0628\u0639\u062f\u06cc \u062f\u0631 \u0636\u0627\u06cc\u0639\u0647\u0654 \u062f\u0631\u0648\u0646\u200c\u0627\u067e\u06cc\u200c\u062a\u0644\u06cc\u0627\u0644 \u062f\u0631\u062c\u0647\u200c\u067e\u0627\u06cc\u06cc\u0646 \u0633\u0631\u0648\u06cc\u06a9\u0633 (LSIL) \u0645\u0639\u0645\u0648\u0644\u0627\u064b \u06a9\u0648\u0644\u067e\u0648\u0633\u06a9\u0648\u067e\u06cc \u0627\u0633\u062a.",
   "interpretation": "\u0636\u0627\u06cc\u0639\u0647\u0654 \u062f\u0631\u0648\u0646\u200c\u0627\u067e\u06cc\u200c\u062a\u0644\u06cc\u0627\u0644 \u062f\u0631\u062c\u0647\u200c\u067e\u0627\u06cc\u06cc\u0646 (LSIL) \u0628\u06cc\u0634\u062a\u0631 \u0646\u0627\u0634\u06cc \u0627\u0632 \u0639\u0641\u0648\u0646\u062a \u0648\u06cc\u0631\u0648\u0633 \u067e\u0627\u067e\u06cc\u0644\u0648\u0645\u0627\u06cc \u0627\u0646\u0633\u0627\u0646\u06cc (HPV) \u0627\u0633\u062a \u0648 \u062f\u0631 \u0632\u0646\u0627\u0646 \u0628\u0627\u0644\u0627\u06cc \u06f2\u06f4 \u0633\u0627\u0644\u060c \u06a9\u0648\u0644\u067e\u0648\u0633\u06a9\u0648\u067e\u06cc \u0628\u0627 \u0646\u0645\u0648\u0646\u0647\u200c\u0628\u0631\u062f\u0627\u0631\u06cc \u0647\u062f\u0641\u200c\u062f\u0627\u0631 \u0631\u0648\u0634 \u0627\u0633\u062a\u0627\u0646\u062f\u0627\u0631\u062f \u0627\u0633\u062a\u061b \u00ab\u062a\u06a9\u0631\u0627\u0631 \u067e\u0627\u067e\u00bb \u062f\u0631 \u0627\u06cc\u0646 \u0633\u0646 \u067e\u06cc\u06af\u06cc\u0631\u06cc \u0646\u0627\u06a9\u0627\u0641\u06cc \u0627\u0633\u062a\u061b \u0635\u0631\u0641 \u00ab\u062a\u062d\u062a \u0646\u0638\u0631 \u06af\u0631\u0641\u062a\u0646\u00bb \u0628\u0631\u0627\u06cc \u0633\u0646\u06cc\u0646 \u06f2\u06f1 \u062a\u0627 \u06f2\u06f4 \u06cc\u0627 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0645\u0646\u0627\u0633\u0628 \u0627\u0633\u062a\u061b \u00ab\u0628\u06cc\u0648\u067e\u0633\u06cc \u0645\u062e\u0627\u0637\u06cc\u00bb \u0628\u062f\u0648\u0646 \u0631\u0627\u0647\u0646\u0645\u0627\u06cc \u06a9\u0648\u0644\u067e\u0648\u0633\u06a9\u0648\u067e\u06cc \u062f\u0642\u062a \u06a9\u0627\u0641\u06cc \u0646\u062f\u0627\u0631\u062f. \u0628\u0646\u0627\u0628\u0631\u0627\u06cc\u0646 \u06a9\u0648\u0644\u067e\u0648\u0633\u06a9\u0648\u067e\u06cc \u0627\u0646\u062a\u062e\u0627\u0628 \u062f\u0631\u0633\u062a \u0627\u0633\u062a.",
   "reasons": ["\u062a\u06a9\u0631\u0627\u0631 \u067e\u0627\u067e \u0627\u0633\u0645\u06cc\u0631 \u0628\u0631\u0627\u06cc LSIL \u062f\u0631 \u0633\u0646 \u06f3\u06f2 \u0633\u0627\u0644 \u067e\u06cc\u06af\u06cc\u0631\u06cc \u0646\u0627\u06a9\u0627\u0641\u06cc \u0627\u0633\u062a\u060c \u06a9\u0648\u0644\u067e\u0648\u0633\u06a9\u0648\u067e\u06cc \u062a\u0631\u062c\u06cc\u062d \u062f\u0627\u0631\u062f.", "\u00ab\u062a\u062d\u062a \u0646\u0638\u0631 \u06af\u0631\u0641\u062a\u0646\u00bb \u0635\u0631\u0641 \u0645\u0646\u0627\u0633\u0628 \u0632\u06cc\u0631 \u06f2\u06f5 \u0633\u0627\u0644 \u06cc\u0627 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0627\u0633\u062a.", "\u06a9\u0648\u0644\u067e\u0648\u0633\u06a9\u0648\u067e\u06cc \u06af\u0627\u0645 \u0627\u0633\u062a\u0627\u0646\u062f\u0627\u0631\u062f \u0628\u0639\u062f\u06cc \u062f\u0631 LSIL \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u0628\u06cc\u0648\u067e\u0633\u06cc \u0645\u062e\u0627\u0637\u06cc \u06a9\u0648\u0631 \u0628\u062f\u0648\u0646 \u0631\u0627\u0647\u0646\u0645\u0627\u06cc \u06a9\u0648\u0644\u067e\u0648\u0633\u06a9\u0648\u067e\u06cc \u0627\u0633\u062a\u0627\u0646\u062f\u0627\u0631\u062f \u0646\u06cc\u0633\u062a."],
  },
  (28, 152): {
   "topic": "sthFocalNextStep",
   "lead": "\u062f\u0631 \u0636\u0627\u06cc\u0639\u0647\u0654 \u06a9\u0627\u0646\u0648\u0646\u06cc \u062f\u06cc\u062f\u0647\u200c\u0634\u062f\u0647 \u062f\u0631 \u0633\u0648\u0646\u0648\u0647\u06cc\u0633\u062a\u0631\u0648\u06af\u0631\u0627\u0641\u06cc\u060c \u0647\u06cc\u0633\u062a\u0631\u0648\u0633\u06a9\u0648\u067e\u06cc \u0628\u0627 \u0628\u06cc\u0648\u067e\u0633\u06cc \u0647\u062f\u0641\u200c\u062f\u0627\u0631 \u0627\u0646\u062a\u062e\u0627\u0628 \u0627\u0648\u0644 \u0627\u0633\u062a.",
   "interpretation": "\u062f\u0631 \u0632\u0646 \u06f4\u06f2\u200c\u0633\u0627\u0644\u0647 \u0628\u0627 \u062e\u0648\u0646\u200c\u0631\u06cc\u0632\u06cc \u0646\u0627\u0645\u0646\u0638\u0645 \u0648 \u0636\u062e\u0627\u0645\u062a \u0622\u0646\u062f\u0648\u0645\u062a\u0631 \u0628\u0627\u0644\u0627\u060c \u06cc\u0627\u0641\u062a\u0646 \u0636\u0627\u06cc\u0639\u0647\u0654 \u06a9\u0627\u0646\u0648\u0646\u06cc (\u0645\u0634\u06a9\u0648\u06a9 \u0628\u0647 \u067e\u0648\u0644\u06cc\u067e) \u062f\u0631 \u0633\u0648\u0646\u0648\u0647\u06cc\u0633\u062a\u0631\u0648\u06af\u0631\u0627\u0641\u06cc\u060c \u0628\u06cc\u0648\u067e\u0633\u06cc \u0647\u062f\u0641\u200c\u062f\u0627\u0631 \u0631\u0627 \u0636\u0631\u0648\u0631\u06cc \u0645\u06cc\u200c\u06a9\u0646\u062f. \u0647\u06cc\u0633\u062a\u0631\u0648\u0633\u06a9\u0648\u067e\u06cc \u0647\u0645 \u062f\u0642\u062a \u062a\u0634\u062e\u06cc\u0635 \u0648 \u0647\u0645 \u0627\u0645\u06a9\u0627\u0646 \u062f\u0631\u0645\u0627\u0646 \u0647\u0645\u200c\u0632\u0645\u0627\u0646 \u0631\u0627 \u0628\u0627\u0644\u0627\u062a\u0631 \u0645\u06cc\u200c\u0628\u0631\u062f\u061b \u0628\u06cc\u0648\u067e\u0633\u06cc \u06a9\u0648\u0631 \u062f\u0631 \u0645\u0637\u0628 \u0645\u0645\u06a9\u0646 \u0627\u0633\u062a \u0636\u0627\u06cc\u0639\u0647\u0654 \u06a9\u0627\u0646\u0648\u0646\u06cc \u0631\u0627 \u0627\u0632 \u062f\u0633\u062a \u0628\u062f\u0647\u062f\u061b \u06a9\u0648\u0631\u062a\u0627\u0698 \u0627\u0646\u062a\u0634\u0627\u0631\u06cc \u0646\u06cc\u0632 \u0647\u062f\u0641\u200c\u062f\u0627\u0631 \u0646\u06cc\u0633\u062a \u0648 \u062f\u0631\u0645\u0627\u0646 \u062f\u0627\u0631\u0648\u06cc\u06cc \u067e\u06cc\u0634 \u0627\u0632 \u062a\u0634\u062e\u06cc\u0635 \u0645\u0646\u0627\u0633\u0628 \u0646\u06cc\u0633\u062a.",
   "reasons": ["\u0647\u06cc\u0633\u062a\u0631\u0648\u0633\u06a9\u0648\u067e\u06cc \u0628\u0627 \u0628\u06cc\u0648\u067e\u0633\u06cc \u0647\u062f\u0641\u200c\u062f\u0627\u0631 \u06af\u0627\u0645 \u062a\u0634\u062e\u06cc\u0635\u06cc \u062f\u0642\u06cc\u0642 \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u0628\u06cc\u0648\u067e\u0633\u06cc \u06a9\u0648\u0631 \u062f\u0631 \u0645\u0637\u0628 \u0636\u0627\u06cc\u0639\u0647\u0654 \u06a9\u0627\u0646\u0648\u0646\u06cc \u0631\u0627 \u0645\u0645\u06a9\u0646 \u0627\u0633\u062a \u0627\u0632 \u062f\u0633\u062a \u0628\u062f\u0647\u062f.", "\u06a9\u0648\u0631\u062a\u0627\u0698 \u062a\u0634\u062e\u06cc\u0635\u06cc \u0628\u062f\u0648\u0646 \u062f\u06cc\u062f \u0645\u0633\u062a\u0642\u06cc\u0645 \u06a9\u0645\u200c\u062a\u0631 \u0627\u0632 \u0647\u06cc\u0633\u062a\u0631\u0648\u0633\u06a9\u0648\u067e\u06cc \u062f\u0642\u062a \u062f\u0627\u0631\u062f.", "\u062f\u0631\u0645\u0627\u0646 \u062f\u0627\u0631\u0648\u06cc\u06cc \u067e\u06cc\u0634 \u0627\u0632 \u062d\u0630\u0641 \u06cc\u0627 \u062a\u0634\u062e\u06cc\u0635 \u0636\u0627\u06cc\u0639\u0647\u0654 \u06a9\u0627\u0646\u0648\u0646\u06cc \u0645\u0646\u0627\u0633\u0628 \u0646\u06cc\u0633\u062a."],
  },
  (28, 153): {
   "topic": "earlyPregSerialHcg",
   "lead": "\u062f\u0631 BHCG \u06f1\u06f0\u06f0\u06f0 \u0628\u0627 \u0633\u0648\u0646\u0648\u06af\u0631\u0627\u0641\u06cc \u0637\u0628\u06cc\u0639\u06cc \u0648 \u0628\u062f\u0648\u0646 \u0636\u0627\u06cc\u0639\u0647 \u0622\u062f\u0646\u06a9\u0633\u0627\u0644\u060c \u0627\u0646\u062f\u0627\u0632\u0647\u200c\u06af\u06cc\u0631\u06cc \u0633\u0644\u0627\u06cc\u0631 BHCG \u06af\u0627\u0645 \u0645\u0646\u0627\u0633\u0628 \u0627\u0633\u062a.",
   "interpretation": "BHCG \u0632\u06cc\u0631 \u00ab\u062d\u062f \u0622\u0633\u062a\u0627\u0646\u0647\u0654 \u0631\u0648\u06cc\u062a \u06a9\u06cc\u0633\u0647\u00bb \u0648 \u0628\u062f\u0648\u0646 \u0639\u0644\u0627\u0626\u0645 \u0642\u0637\u0639\u06cc EP\u060c \u062a\u0641\u0633\u06cc\u0631 \u0642\u0637\u0639\u06cc \u0631\u0627 \u0646\u0645\u06cc\u200c\u062f\u0647\u062f. \u0633\u0648\u0646\u0648 \u062f\u0648\u0628\u0627\u0631\u0647 \u0648 \u0627\u0646\u062f\u0627\u0632\u0647\u200c\u06af\u06cc\u0631\u06cc \u0633\u0644\u0627\u06cc\u0631 BHCG (\u0647\u0631 \u06f4\u06f8 \u0633\u0627\u0639\u062a) \u0628\u0631\u0627\u06cc \u0627\u0641\u062a\u0631\u0627\u0642 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u062f\u0627\u062e\u0644\u200c\u0631\u062d\u0645\u06cc \u0637\u0628\u06cc\u0639\u06cc \u0628\u0633\u06cc\u0627\u0631 \u0632\u0648\u062f\u0631\u0633 \u0627\u0632 EP \u0644\u0627\u0632\u0645 \u0627\u0633\u062a\u061b \u0644\u0627\u067e\u0627\u0631\u0648\u0633\u06a9\u0648\u067e\u06cc \u062a\u0634\u062e\u06cc\u0635\u06cc \u06cc\u0627 D&C \u0628\u062f\u0648\u0646 \u0627\u0646\u062f\u06cc\u06a9\u0627\u0633\u06cc\u0648\u0646\u060c \u0628\u0647\u200c\u0637\u0631\u0632 \u0646\u0627\u0628\u062c\u0627 \u062a\u0647\u0627\u062c\u0645\u06cc \u0627\u0633\u062a\u061b \u0645\u062a\u0648\u062a\u0631\u06a9\u0633\u0627\u062a \u0628\u062f\u0648\u0646 \u062a\u0623\u06cc\u06cc\u062f EP \u062e\u0644\u0627\u0641 \u0627\u0633\u062a\u0627\u0646\u062f\u0627\u0631\u062f. \u0631\u0648\u0634 \u0627\u0633\u062a\u0627\u0646\u062f\u0627\u0631\u062f: \u067e\u06cc\u06af\u06cc\u0631\u06cc \u0633\u0644\u0627\u06cc\u0631.",
   "reasons": ["\u0627\u0646\u062f\u0627\u0632\u0647\u200c\u06af\u06cc\u0631\u06cc \u0633\u0644\u0627\u06cc\u0631 BHCG \u0631\u0648\u0634 \u0627\u0633\u062a\u0627\u0646\u062f\u0627\u0631\u062f \u067e\u06cc\u06af\u06cc\u0631\u06cc \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0632\u0648\u062f\u0631\u0633 \u063a\u06cc\u0631\u0642\u0637\u0639\u06cc \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u0644\u0627\u067e\u0627\u0631\u0648\u0633\u06a9\u0648\u067e\u06cc \u062f\u0631 BHCG \u06f1\u06f0\u06f0\u06f0 \u0628\u062f\u0648\u0646 \u0634\u0648\u0627\u0647\u062f EP\u060c \u06af\u0627\u0645 \u0627\u0648\u0644 \u0646\u06cc\u0633\u062a.", "D&C \u0628\u062f\u0648\u0646 \u0634\u0648\u0627\u0647\u062f \u0646\u0627\u0642\u0635 \u0634\u062f\u0646 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc\u060c \u0642\u0628\u0644 \u0627\u0632 \u062a\u0641\u06a9\u06cc\u06a9 EP \u0646\u0627\u0645\u0646\u0627\u0633\u0628 \u0627\u0633\u062a.", "\u0645\u062a\u0648\u062a\u0631\u06a9\u0633\u0627\u062a \u0628\u062f\u0648\u0646 \u062a\u0623\u06cc\u06cc\u062f \u0628\u0627 BHCG \u06f1\u06f0\u06f0\u06f0 \u0648 \u0633\u0648\u0646\u0648\u06cc \u0637\u0628\u06cc\u0639\u06cc \u06a9\u0627\u0647\u0646\u062f\u0647\u0654 \u062f\u0642\u062a \u0627\u0633\u062a."],
  },
  (28, 154): {
   "topic": "gtnRisingSingle",
   "lead": "\u062f\u0631 \u0631\u0648\u0646\u062f \u0635\u0639\u0648\u062f\u06cc BHCG \u067e\u0633 \u0627\u0632 \u062a\u062e\u0644\u06cc\u0647\u0654 \u0645\u0648\u0644 \u0628\u0627 \u0645\u0639\u0627\u06cc\u0646\u0647 \u0648 \u062a\u0635\u0648\u06cc\u0631 \u0637\u0628\u06cc\u0639\u06cc\u060c \u0634\u0631\u0648\u0639 \u0634\u06cc\u0645\u06cc\u200c\u062f\u0631\u0645\u0627\u0646\u06cc \u062a\u06a9\u200c\u062f\u0627\u0631\u0648\u06cc\u06cc \u0645\u0646\u0627\u0633\u0628 \u0627\u0633\u062a.",
   "interpretation": "\u0645\u0639\u06cc\u0627\u0631 \u062a\u0634\u062e\u06cc\u0635 \u0628\u06cc\u0645\u0627\u0631\u06cc \u062a\u0631\u0648\u0641\u0648\u0628\u0644\u0627\u0633\u062a\u06cc\u06a9 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc (GTN) \u067e\u0633 \u0627\u0632 \u0645\u0648\u0644\u060c \u0627\u0641\u0632\u0627\u06cc\u0634 \u0628\u06cc\u0634 \u0627\u0632 \u062f\u0647\u200c\u062f\u0631\u0635\u062f\u06cc BHCG \u062f\u0631 \u0633\u0647 \u0647\u0641\u062a\u0647\u0654 \u067e\u06cc\u0627\u067e\u06cc \u06cc\u0627 \u062a\u0648\u0642\u0641 \u067e\u0644\u062a\u0648\u0626\u06cc \u0622\u0646 \u0627\u0633\u062a. \u062f\u0631 \u0646\u0628\u0648\u062f \u0645\u062a\u0627\u0633\u062a\u0627\u0632 \u0645\u0634\u0647\u0648\u062f \u0648 \u0628\u0627 \u0633\u0627\u0628\u0642\u0647\u0654 \u0641\u0642\u0637 \u0645\u0648\u0644\u060c \u0628\u06cc\u0645\u0627\u0631 \u062f\u0631 \u06af\u0631\u0648\u0647 \u06a9\u0645\u200c\u062e\u0637\u0631 \u0642\u0631\u0627\u0631 \u0645\u06cc\u200c\u06af\u06cc\u0631\u062f \u0648 \u0634\u06cc\u0645\u06cc\u200c\u062f\u0631\u0645\u0627\u0646\u06cc \u062a\u06a9\u200c\u062f\u0627\u0631\u0648\u06cc\u06cc (\u0645\u062a\u0648\u062a\u0631\u06a9\u0633\u0627\u062a \u06cc\u0627 \u0622\u06a9\u062a\u06cc\u0646\u0648\u0645\u0627\u06cc\u0633\u06cc\u0646) \u062e\u0637 \u0627\u0648\u0644 \u0627\u0633\u062a\u061b \u0634\u06cc\u0645\u06cc\u200c\u062f\u0631\u0645\u0627\u0646\u06cc \u062a\u0631\u06a9\u06cc\u0628\u06cc \u0628\u0631\u0627\u06cc \u0645\u0648\u0627\u0631\u062f \u067e\u0631\u062e\u0637\u0631 \u06cc\u0627 \u0645\u0642\u0627\u0648\u0645\u060c \u067e\u0631\u062a\u0648\u062f\u0631\u0645\u0627\u0646\u06cc \u0646\u0642\u0634 \u0645\u062d\u062f\u0648\u062f \u0648 \u0647\u06cc\u0633\u062a\u0631\u06a9\u062a\u0648\u0645\u06cc \u0641\u0642\u0637 \u062f\u0631 \u0634\u0631\u0627\u06cc\u0637 \u062e\u0627\u0635 \u0645\u0637\u0631\u062d \u0645\u06cc\u200c\u0634\u0648\u062f.",
   "reasons": ["\u0634\u06cc\u0645\u06cc\u200c\u062f\u0631\u0645\u0627\u0646\u06cc \u062a\u06a9\u200c\u062f\u0627\u0631\u0648\u06cc\u06cc \u062e\u0637 \u0627\u0648\u0644 GTN \u06a9\u0645\u200c\u062e\u0637\u0631 \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u0634\u06cc\u0645\u06cc\u200c\u062f\u0631\u0645\u0627\u0646\u06cc \u062a\u0631\u06a9\u06cc\u0628\u06cc \u062f\u0631 \u067e\u0631\u062e\u0637\u0631/\u0645\u0642\u0627\u0648\u0645 \u0628\u0647 \u06a9\u0627\u0631 \u0645\u06cc\u200c\u0631\u0648\u062f.", "\u067e\u0631\u062a\u0648\u062f\u0631\u0645\u0627\u0646\u06cc \u062f\u0631 GTN \u0627\u0633\u062a\u0627\u0646\u062f\u0627\u0631\u062f \u062e\u0637 \u0627\u0648\u0644 \u0646\u06cc\u0633\u062a.", "\u0647\u06cc\u0633\u062a\u0631\u06a9\u062a\u0648\u0645\u06cc \u0641\u0642\u0637 \u062f\u0631 \u0642\u0637\u0639\u06cc\u200c\u0634\u062f\u0646 \u06cc\u0627 \u062e\u0648\u0646\u200c\u0631\u06cc\u0632\u06cc \u0645\u0642\u0627\u0648\u0645 \u0645\u062f\u0646\u0638\u0631 \u0627\u0633\u062a."],
  },
  (28, 155): {
   "topic": "rhogamDoseKleihauer",
   "lead": "\u0647\u0631 \u0648\u06cc\u0627\u0644 \u0631\u0648\u06af\u0627\u0645 \u06f1\u06f2 \u0645\u06cc\u06a9\u0631\u0648\u06af\u0631\u0645\u061f \u062e\u06cc\u0631 \u2014 \u0647\u0631 \u0648\u06cc\u0627\u0644 \u0627\u0633\u062a\u0627\u0646\u062f\u0627\u0631\u062f (\u06f3\u06f0\u06f0 \u0645\u06cc\u06a9\u0631\u0648\u06af\u0631\u0645) \u062a\u0642\u0631\u06cc\u0628\u0627\u064b \u06f3\u06f0 \u0645\u06cc\u0644\u06cc\u200c\u0644\u06cc\u062a\u0631 \u062e\u0648\u0646 \u06a9\u0627\u0645\u0644 \u062c\u0646\u06cc\u0646 \u0631\u0627 \u067e\u0648\u0634\u0634 \u0645\u06cc\u200c\u062f\u0647\u062f\u061b \u0622\u0632\u0645\u0648\u0646 \u0627\u06cc\u0646\u062c\u0627 \u067e\u0627\u0633\u062e \u06f6\u06f0\u06f0 \u0631\u0627 \u0628\u0647 \u062f\u0633\u062a \u0645\u06cc\u200c\u062f\u0647\u062f.",
   "interpretation": "\u0622\u0632\u0645\u0648\u0646 \u06a9\u0644\u0627\u06cc\u0647\u0648\u0631-\u0628\u062a\u06a9\u0647 \u06f6\u06f0 \u0645\u06cc\u0644\u06cc\u200c\u0644\u06cc\u062a\u0631 \u062e\u0648\u0646 \u062c\u0646\u06cc\u0646\u06cc \u0648\u0627\u0631\u062f \u06af\u0631\u062f\u0634 \u0645\u0627\u062f\u0631 \u0631\u0627 \u0646\u0634\u0627\u0646 \u0645\u06cc\u200c\u062f\u0647\u062f\u061b \u0647\u0631 \u0648\u06cc\u0627\u0644 \u0627\u0633\u062a\u0627\u0646\u062f\u0627\u0631\u062f \u0631\u0648\u06af\u0627\u0645 \u062d\u062f\u0648\u062f \u06f3\u06f0 \u0645\u06cc\u0644\u06cc\u200c\u0644\u06cc\u062a\u0631 \u062e\u0648\u0646 \u06a9\u0627\u0645\u0644 \u062c\u0646\u06cc\u0646 \u0631\u0627 \u067e\u0648\u0634\u0634 \u0645\u06cc\u200c\u062f\u0647\u062f\u060c \u0628\u0646\u0627\u0628\u0631\u0627\u06cc\u0646 \u062f\u0648 \u0648\u06cc\u0627\u0644 (\u0645\u0639\u0627\u062f\u0644 \u06af\u0632\u06cc\u0646\u0647\u0654 \u06f6\u06f0\u06f0) \u0644\u0627\u0632\u0645 \u0627\u0633\u062a. \u06af\u0632\u06cc\u0646\u0647\u200c\u0647\u0627\u06cc \u06f1\u06f5\u06f0 \u0648 \u06f3\u06f0\u06f0 \u0648 \u06f4\u06f5\u06f0 \u06a9\u0645\u200c\u062a\u0631 \u0627\u0632 \u0646\u06cc\u0627\u0632 \u0645\u062d\u0627\u0633\u0628\u0647\u200c\u0634\u062f\u0647\u200c\u0627\u0646\u062f \u0648 \u067e\u0648\u0634\u0634 \u06a9\u0627\u0641\u06cc \u0646\u062f\u0627\u0631\u0646\u062f.",
   "reasons": ["\u06f1\u06f5\u06f0 \u0645\u06cc\u06a9\u0631\u0648\u06af\u0631\u0645 \u0628\u0631\u0627\u06cc 60cc \u062e\u0648\u0646 \u062c\u0646\u06cc\u0646\u06cc \u06a9\u0627\u0641\u06cc \u0646\u06cc\u0633\u062a.", "\u06f3\u06f0\u06f0 \u0645\u06cc\u06a9\u0631\u0648\u06af\u0631\u0645 \u06cc\u06a9 \u0648\u06cc\u0627\u0644 \u0641\u0642\u0637 ~\u06f3\u06f0 \u0633\u06cc\u200c\u0633\u06cc \u0631\u0627 \u067e\u0648\u0634\u0634 \u0645\u06cc\u200c\u062f\u0647\u062f.", "\u06f4\u06f5\u06f0 \u0645\u06cc\u06a9\u0631\u0648\u06af\u0631\u0645 \u062f\u0631 \u0634\u0634\u0648\u06cc\u0627\u0644 \u0648\u0627\u0642\u0639\u06cc \u0628\u0647\u200c\u06a9\u0627\u0631 \u0646\u0645\u06cc\u200c\u0631\u0648\u062f.", "\u062f\u0648 \u0648\u06cc\u0627\u0644 \u06f3\u06f0\u06f0 \u0645\u06cc\u06a9\u0631\u0648\u06af\u0631\u0645\u06cc \u06cc\u0639\u0646\u06cc \u06f6\u06f0\u06f0 \u0645\u06cc\u06a9\u0631\u0648\u06af\u0631\u0645 \u0644\u0627\u0632\u0645 \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d."],
  },
  (28, 156): {
   "topic": "abrupTermination",
   "lead": "\u062f\u0631 \u0633\u0646 \u06f3\u06f3 \u0647\u0641\u062a\u0647 \u0628\u0627 \u067e\u0631\u0647\u200c\u0627\u06a9\u0644\u0627\u0645\u067e\u0633\u06cc \u0634\u062f\u06cc\u062f \u0627\u062d\u062a\u0645\u0627\u0644\u06cc\u060c \u0627\u0644\u06cc\u06af\u0648\u0647\u06cc\u062f\u0631\u0627\u0645\u0646\u06cc\u0648\u0633 \u0648 \u0631\u062d\u0645 \u0647\u0627\u06cc\u067e\u0631\u062a\u0648\u0646\u06cc\u06a9 (\u062a\u0646\u0634 \u0628\u0627\u0644\u0627\u062a\u0631)\u060c \u0627\u0642\u062f\u0627\u0645 \u0645\u0646\u0627\u0633\u0628 \u062e\u062a\u0645 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0641\u0648\u0631\u06cc \u0642\u0628\u0644 \u0627\u0632 \u062a\u06a9\u0645\u06cc\u0644 \u062f\u0648\u0632 \u0627\u0633\u062a\u0631\u0648\u0626\u06cc\u062f \u0627\u0633\u062a.",
   "interpretation": "\u062a\u0631\u06a9\u06cc\u0628 \u0641\u0634\u0627\u0631 160/110\u060c \u06a9\u0627\u0647\u0634 \u0645\u0627\u06cc\u0639 \u0622\u0645\u0646\u06cc\u0648\u062a\u06cc\u06a9 \u0648 \u0631\u062d\u0645 \u0647\u0627\u06cc\u067e\u0631\u062a\u0648\u0646\u06cc\u06a9 \u0646\u0634\u0627\u0646\u200c\u062f\u0647\u0646\u062f\u0647\u0654 \u0627\u06cc\u0633\u06a9\u0645\u06cc/\u0634\u0631\u0627\u06cc\u0637 \u067e\u0631\u062e\u0637\u0631 \u0645\u0627\u062f\u0631\u2013\u062c\u0641\u062a \u0627\u0633\u062a (\u0645\u0645\u06a9\u0646 \u0627\u0633\u062a \u0628\u0627 \u062f\u06a9\u0648\u0644\u0645\u0627\u0646 \u0647\u0645 \u062e\u0648\u0627\u0646\u06cc \u0634\u0648\u062f). \u0628\u06cc\u0645 \u0628\u0627 \u00ab\u062e\u0637\u0631 \u0641\u0648\u0631\u06cc\u062a\u00bb \u0628\u0647 \u0633\u0644\u0627\u0645\u062a \u0645\u0627\u062f\u0631/\u062c\u0646\u06cc\u0646 \u062f\u0631 \u06f3\u06f3 \u0647\u0641\u062a\u0647\u060c \u0627\u0646\u062a\u0638\u0627\u0631 \u06f4\u06f8 \u0633\u0627\u0639\u062a\u06cc \u0628\u0631\u0627\u06cc \u06a9\u0648\u0631\u062a\u0648\u0646 \u0645\u06cc\u200c\u062a\u0648\u0627\u0646\u062f \u062e\u0637\u0631\u0646\u0627\u06a9 \u0628\u0627\u0634\u062f\u061b \u0635\u0631\u0641\u0627\u064b \u062f\u0631\u0645\u0627\u0646 \u0636\u062f\u0641\u0634\u0627\u0631 \u06cc\u0627 \u0633\u0648\u0644\u0641\u0627\u062a \u0645\u0646\u06cc\u0632\u06cc\u0645 \u0635\u0631\u0641\u0627\u064b \u062a\u0623\u062e\u06cc\u0631 \u062f\u0631 \u062e\u062a\u0645 \u0627\u0633\u062a.",
   "reasons": ["\u062e\u062a\u0645 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0641\u0648\u0631\u06cc \u0628\u0627 \u062b\u0628\u062a \u0634\u0631\u0627\u06cc\u0637 \u0641\u0639\u0644\u06cc \u0628\u0647\u062a\u0631\u06cc\u0646 \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u06f4\u06f8 \u0633\u0627\u0639\u062a \u062f\u0627\u062f\u0646 \u06a9\u0648\u0631\u062a\u0648\u0646 \u062f\u0631 \u0634\u0631\u0627\u06cc\u0637 \u067e\u0631\u062e\u0637\u0631 \u06a9\u0646\u0648\u0646\u06cc \u0631\u06cc\u0633\u06a9 \u062f\u0627\u0631\u062f.", "\u0635\u0631\u0641\u0627\u064b \u062f\u0631\u0645\u0627\u0646 \u0636\u062f\u0641\u0634\u0627\u0631\u060c \u062e\u062a\u0645 \u0631\u0627 \u0639\u0642\u0628 \u0645\u06cc\u200c\u0627\u0646\u062f\u0627\u0632\u062f.", "\u0633\u0648\u0644\u0641\u0627\u062a \u0645\u0646\u06cc\u0632\u06cc\u0645 \u0628\u0647\u200c\u062a\u0646\u0647\u0627\u06cc\u06cc \u067e\u0627\u0633\u062e \u0642\u0637\u0639\u06cc \u0646\u06cc\u0633\u062a \u0648 \u0641\u0642\u0637 \u0628\u0631\u0627\u06cc \u067e\u06cc\u0634\u06af\u06cc\u0631\u06cc \u0627\u0632 \u0627\u06a9\u0644\u0627\u0645\u067e\u0633\u06cc \u0627\u0633\u062a."],
  },
  (28, 157): {
   "topic": "firstTrimDownScreen",
   "lead": "\u063a\u0631\u0628\u0627\u0644\u06af\u0631\u06cc \u0633\u0647\u200c\u0645\u0627\u0647\u0647\u0654 \u0627\u0648\u0644 \u0633\u0646\u062f\u0631\u0645 \u062f\u0627\u0648\u0646 \u0628\u0627 \u062a\u0631\u06a9\u06cc\u0628 \u0634\u0641\u0627\u0641\u06cc\u062a \u067e\u0633\u200c\u06af\u0631\u062f\u0646\u06cc (NT) \u0648 \u062f\u0648 \u0645\u0627\u0631\u06a9\u0631 \u0633\u0631\u0645\u06cc \u0627\u0646\u062c\u0627\u0645 \u0645\u06cc\u200c\u0634\u0648\u062f.",
   "interpretation": "\u063a\u0631\u0628\u0627\u0644\u06af\u0631\u06cc \u0645\u0624\u062b\u0631 \u0633\u0647\u200c\u0645\u0627\u0647\u0647\u0654 \u0627\u0648\u0644 (\u06f1\u06f1 \u062a\u0627 \u06f1\u06f3 \u0647\u0641\u062a\u0647 \u0648 \u0634\u0634 \u0631\u0648\u0632) \u0628\u0631 \u067e\u0627\u06cc\u0647\u0654 \u062a\u0631\u06a9\u06cc\u0628 \u0633\u0648\u0646\u0648\u06af\u0631\u0627\u0641\u06cc \u0634\u0641\u0627\u0641\u06cc\u062a \u0646\u0627\u062d\u06cc\u0647\u0654 \u067e\u0633\u200c\u06af\u0631\u062f\u0646\u06cc \u0648 \u0645\u0627\u0631\u06a9\u0631\u0647\u0627\u06cc \u0633\u0631\u0645\u06cc \u0628\u062a\u0627-HCG \u0622\u0632\u0627\u062f \u0648 PAPP-A \u0627\u0633\u062a\u061b \u0622\u0646\u0648\u0645\u0627\u0644\u06cc\u200c\u0627\u0633\u06a9\u0646 \u0645\u062a\u0639\u0627\u0642\u0628\u0627\u064b \u062f\u0631 \u0647\u0641\u062a\u0647\u0654 \u06f1\u06f8 \u062a\u0627 \u06f2\u06f2 \u0627\u0646\u062c\u0627\u0645 \u0645\u06cc\u200c\u0634\u0648\u062f\u061b \u062a\u0631\u06a9\u06cc\u0628 \u0622\u0644\u0641\u0627\u0641\u062a\u0648\u067e\u0631\u0648\u062a\u0626\u06cc\u0646 \u0648 \u0627\u06cc\u0646\u0647\u06cc\u0628\u06cc\u0646 \u0645\u0631\u0628\u0648\u0637 \u0628\u0647 \u0622\u0632\u0645\u0648\u0646 \u0686\u0647\u0627\u0631\u06af\u0627\u0646\u0647\u0654 \u0633\u0647\u200c\u0645\u0627\u0647\u0647\u0654 \u062f\u0648\u0645 \u0627\u0633\u062a\u061b \u0648 \u0646\u0645\u0648\u0646\u0647\u200c\u0628\u0631\u062f\u0627\u0631\u06cc \u067e\u0631\u0632\u0647\u0627\u06cc \u06a9\u0648\u0631\u06cc\u0648\u0646\u06cc (CVS) \u0631\u0648\u0634 \u062a\u0634\u062e\u06cc\u0635\u06cc \u0646\u0641\u0648\u0630\u06af\u0631 \u0627\u0633\u062a \u0646\u0647 \u063a\u0631\u0628\u0627\u0644\u06af\u0631\u06cc.",
   "reasons": ["\u0622\u0646\u0648\u0645\u0627\u0644\u06cc\u200c\u0627\u0633\u06a9\u0646 \u0645\u0631\u0628\u0648\u0637 \u0628\u0647 \u0633\u0647\u200c\u0645\u0627\u0647\u0647\u0654 \u062f\u0648\u0645 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0627\u0633\u062a \u0646\u0647 \u063a\u0631\u0628\u0627\u0644\u06af\u0631\u06cc \u0627\u0648\u0644\u06cc\u0647.", "\u062a\u0631\u06a9\u06cc\u0628 NT \u0648 \u0628\u062a\u0627-HCG \u0622\u0632\u0627\u062f \u0648 PAPP-A \u0631\u0648\u0634 \u0627\u0633\u062a\u0627\u0646\u062f\u0627\u0631\u062f \u0633\u0647\u200c\u0645\u0627\u0647\u0647\u0654 \u0627\u0648\u0644 \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u062a\u0631\u06a9\u06cc\u0628 \u0622\u0644\u0641\u0627\u0641\u062a\u0648\u067e\u0631\u0648\u062a\u0626\u06cc\u0646 \u0648 \u0627\u06cc\u0646\u0647\u06cc\u0628\u06cc\u0646 \u0645\u0631\u0628\u0648\u0637 \u0628\u0647 \u0622\u0632\u0645\u0648\u0646 \u0686\u0647\u0627\u0631\u06af\u0627\u0646\u0647\u0654 \u0633\u0647\u200c\u0645\u0627\u0647\u0647\u0654 \u062f\u0648\u0645 \u0627\u0633\u062a.", "CVS \u0631\u0648\u0634 \u062a\u0634\u062e\u06cc\u0635\u06cc \u0646\u0641\u0648\u0630\u06af\u0631 \u0627\u0633\u062a \u0648 \u0641\u0642\u0637 \u062f\u0631 \u0645\u0648\u0627\u0631\u062f \u067e\u0631\u062e\u0637\u0631 \u0627\u0646\u062c\u0627\u0645 \u0645\u06cc\u200c\u0634\u0648\u062f."],
  },
  (28, 158): {
   "topic": "superimposedPreeclampsia",
   "lead": "\u0641\u0634\u0627\u0631 \u062e\u0648\u0646 \u0645\u0632\u0645\u0646 \u0645\u0634\u062e\u0635 \u062f\u0631 \u0633\u0647\u200c\u0645\u0627\u0647\u0647\u0654 \u0627\u0648\u0644 \u06a9\u0647 \u0628\u0639\u062f\u0627\u064b \u0628\u0627 \u067e\u0631\u0648\u062a\u0626\u06cc\u0646\u0648\u0631\u06cc \u0648 \u062a\u0631\u0648\u0645\u0628\u0648\u0633\u06cc\u062a\u0648\u067e\u0646\u06cc \u0647\u0645\u0631\u0627\u0647 \u0634\u0648\u062f\u060c \u062a\u0639\u0631\u06cc\u0641 \u067e\u0631\u0647\u200c\u0627\u06a9\u0644\u0627\u0645\u067e\u0633\u06cc \u0641\u0648\u0642\u200c\u0627\u0641\u0632\u0648\u062f\u0647 \u0628\u0631 \u0641\u0634\u0627\u0631 \u0645\u0632\u0645\u0646 \u0627\u0633\u062a.",
   "interpretation": "\u0641\u0634\u0627\u0631 \u06f1\u06f4\u06f0/\u06f9\u06f0 \u062f\u0631 \u0633\u0647\u200c\u0645\u0627\u0647\u0647\u0654 \u0627\u0648\u0644 \u06cc\u0639\u0646\u06cc \u067e\u0631\u0641\u0634\u0627\u0631\u06cc \u062e\u0648\u0646 \u0645\u0632\u0645\u0646\u061b \u0633\u067e\u0633 \u062f\u0631 \u0647\u0641\u062a\u0647\u0654 \u06f3\u06f0 \u0622\u0644\u0628\u0648\u0645\u06cc\u0646 \u0627\u062f\u0631\u0627\u0631 \u0645\u062b\u0628\u062a \u0648 \u067e\u0644\u0627\u06a9\u062a \u06f8\u06f0 \u0647\u0632\u0627\u0631 \u06af\u0632\u0627\u0631\u0634 \u0634\u062f\u0647 \u0627\u0633\u062a \u06a9\u0647 \u0646\u0634\u0627\u0646\u200c\u062f\u0647\u0646\u062f\u0647\u0654 \u0627\u0641\u0632\u0648\u062f\u0647\u200c\u0634\u062f\u0646 \u067e\u0631\u0647\u200c\u0627\u06a9\u0644\u0627\u0645\u067e\u0633\u06cc \u0628\u0631 \u0641\u0634\u0627\u0631 \u0645\u0632\u0645\u0646 \u0628\u0647 \u0646\u0627\u0645 \u067e\u0631\u0647\u200c\u0627\u06a9\u0644\u0627\u0645\u067e\u0633\u06cc \u0641\u0648\u0642\u200c\u0627\u0641\u0632\u0648\u062f\u0647 \u0627\u0633\u062a. \u00ab\u067e\u0631\u0647\u200c\u0627\u06a9\u0644\u0627\u0645\u067e\u0633\u06cc \u062e\u0641\u06cc\u0641\u00bb \u0628\u062f\u0648\u0646 \u0628\u0633\u062a\u0631 \u0641\u0634\u0627\u0631 \u0645\u0632\u0645\u0646 \u062f\u0631\u0633\u062a \u0646\u06cc\u0633\u062a \u0648 \u00ab\u067e\u0631\u0641\u0634\u0627\u0631\u06cc \u0645\u0632\u0645\u0646\u00bb \u0628\u0647\u200c\u062a\u0646\u0647\u0627\u06cc\u06cc \u062a\u0631\u0648\u0645\u0628\u0648\u0633\u06cc\u062a\u0648\u067e\u0646\u06cc \u0648 \u067e\u0631\u0648\u062a\u0626\u06cc\u0646\u0648\u0631\u06cc \u062c\u062f\u06cc\u062f \u0631\u0627 \u062a\u0648\u0636\u06cc\u062d \u0646\u0645\u06cc\u200c\u062f\u0647\u062f.",
   "reasons": ["\u067e\u0631\u0647\u200c\u0627\u06a9\u0644\u0627\u0645\u067e\u0633\u06cc \u062e\u0641\u06cc\u0641 \u0628\u062f\u0648\u0646 \u062f\u0631\u0646\u0638\u0631 \u06af\u0631\u0641\u062a\u0646 \u0641\u0634\u0627\u0631 \u0645\u0632\u0645\u0646 \u0642\u0628\u0644\u06cc \u0635\u062f\u0642 \u0646\u0645\u06cc\u200c\u06a9\u0646\u062f.", "\u067e\u0631\u0647\u200c\u0627\u06a9\u0644\u0627\u0645\u067e\u0633\u06cc \u0634\u062f\u06cc\u062f \u0628\u0647\u200c\u062a\u0646\u0647\u0627\u06cc\u06cc \u0628\u0633\u062a\u0631 \u0641\u0634\u0627\u0631 \u0645\u0632\u0645\u0646 \u0627\u0648\u0644\u06cc\u0647 \u0631\u0627 \u0644\u062d\u0627\u0638 \u0646\u0645\u06cc\u200c\u06a9\u0646\u062f.", "\u0641\u0634\u0627\u0631 \u0645\u0632\u0645\u0646 + \u067e\u0631\u0648\u062a\u0626\u06cc\u0646\u0648\u0631\u06cc \u0648 \u062a\u0631\u0648\u0645\u0628\u0648\u0633\u06cc\u062a\u0648\u067e\u0646\u06cc \u062c\u062f\u06cc\u062f = \u067e\u0631\u0647\u200c\u0627\u06a9\u0644\u0627\u0645\u067e\u0633\u06cc \u0641\u0648\u0642\u200c\u0627\u0641\u0632\u0648\u062f\u0647\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u067e\u0631\u0641\u0634\u0627\u0631\u06cc \u0645\u0632\u0645\u0646 \u0628\u0647\u200c\u062a\u0646\u0647\u0627\u06cc\u06cc \u062a\u0631\u0648\u0645\u0628\u0648\u0633\u06cc\u062a\u0648\u067e\u0646\u06cc \u0648 \u0622\u0644\u0628\u0648\u0645\u06cc\u0646\u0648\u0631\u06cc \u062c\u062f\u06cc\u062f \u0631\u0627 \u062a\u0648\u0636\u06cc\u062d \u0646\u0645\u06cc\u200c\u062f\u0647\u062f."],
  },
  (28, 159): {
   "topic": "gdmScreeningLowRisk",
   "lead": "\u0632\u0645\u0627\u0646 \u0627\u0633\u062a\u0627\u0646\u062f\u0627\u0631\u062f \u063a\u0631\u0628\u0627\u0644\u06af\u0631\u06cc GDM \u062f\u0631 \u06af\u0631\u0648\u0647 \u06a9\u0645\u200c\u062e\u0637\u0631 \u06f2\u06f4-\u06f2\u06f8 \u0647\u0641\u062a\u06af\u06cc \u0627\u0633\u062a.",
   "interpretation": "\u062f\u0631 \u0627\u0641\u0631\u0627\u062f \u06a9\u0645\u200c\u062e\u0637\u0631 (\u0633\u0646 \u062c\u0648\u0627\u0646\u060c \u0648\u0632\u0646 \u0646\u0631\u0645\u0627\u0644\u060c \u0628\u062f\u0648\u0646 \u0633\u0627\u0628\u0642\u0647\u0654 \u0641\u0627\u0645\u06cc\u0644\u06cc\u060c \u0628\u062f\u0648\u0646 \u0633\u0627\u0628\u0642\u0647\u0654 \u062f\u06cc\u0627\u0628\u062a \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u06cc\u0627 \u0645\u0627\u06a9\u0631\u0648\u0632\u0648\u0645\u06cc)\u060c \u0647\u0645\u0627\u0646 \u0632\u0645\u0627\u0646 \u0627\u0633\u062a\u0627\u0646\u062f\u0627\u0631\u062f \u06cc\u0639\u0646\u06cc \u06f2\u06f4 \u062a\u0627 \u06f2\u06f8 \u0647\u0641\u062a\u0647 \u062a\u0648\u0635\u06cc\u0647 \u0645\u06cc\u200c\u0634\u0648\u062f. \u063a\u0631\u0628\u0627\u0644\u06af\u0631\u06cc \u062f\u0631 \u0627\u0648\u0644\u06cc\u0646 \u0648\u06cc\u0632\u06cc\u062a \u0641\u0642\u0637 \u0628\u0631\u0627\u06cc \u06af\u0631\u0648\u0647\u200c\u0647\u0627\u06cc \u067e\u0631\u062e\u0637\u0631 \u0627\u0633\u062a \u0648 \u0647\u0641\u062a\u0647\u200c\u0647\u0627\u06cc \u06f1\u06f1-\u06f1\u06f4 \u06cc\u0627 \u06f1\u06f5-\u06f2\u06f0 \u067e\u0646\u062c\u0631\u0647\u0654 \u0631\u0648\u062a\u06cc\u0646 \u06a9\u0645\u200c\u062e\u0637\u0631\u0647\u0627 \u0646\u06cc\u0633\u062a\u0646\u062f.",
   "reasons": ["\u0627\u0648\u0644\u06cc\u0646 \u0648\u06cc\u0632\u06cc\u062a \u0641\u0642\u0637 \u062f\u0631 \u06af\u0631\u0648\u0647\u200c\u0647\u0627\u06cc \u067e\u0631\u062e\u0637\u0631 \u0628\u0627 \u062a\u0633\u062a \u0627\u0648\u0644\u06cc\u0647 \u0627\u0646\u062c\u0627\u0645 \u0645\u06cc\u200c\u0634\u0648\u062f.", "\u0647\u0641\u062a\u0647\u200c\u0647\u0627\u06cc \u06f1\u06f1 \u062a\u0627 \u06f1\u06f4 \u067e\u0646\u062c\u0631\u0647\u0654 \u0631\u0648\u062a\u06cc\u0646 \u063a\u0631\u0628\u0627\u0644\u06af\u0631\u06cc \u062f\u06cc\u0627\u0628\u062a \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0646\u06cc\u0633\u062a.", "\u0647\u0641\u062a\u0647\u200c\u0647\u0627\u06cc \u06f1\u06f5 \u062a\u0627 \u06f2\u06f0 \u067e\u0646\u062c\u0631\u0647\u0654 \u0627\u0633\u062a\u0627\u0646\u062f\u0627\u0631\u062f \u0628\u0631\u0627\u06cc \u06af\u0631\u0648\u0647 \u06a9\u0645\u200c\u062e\u0637\u0631 \u0646\u06cc\u0633\u062a.", "\u06f2\u06f4 \u062a\u0627 \u06f2\u06f8 \u0647\u0641\u062a\u06af\u06cc \u0632\u0645\u0627\u0646 \u0627\u0633\u062a\u0627\u0646\u062f\u0627\u0631\u062f \u063a\u0631\u0628\u0627\u0644\u06af\u0631\u06cc \u062f\u0631 \u06a9\u0645\u200c\u062e\u0637\u0631\u0647\u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d."],
  },
  (28, 160): {
   "topic": "safeAntibioticPregnancy",
   "lead": "\u0627\u0631\u06cc\u062a\u0631\u0648\u0645\u0627\u06cc\u0633\u06cc\u0646 \u062f\u0631 \u0647\u0641\u062a\u0647\u0654 \u06f1\u06f0 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0628\u0627 \u0627\u0637\u0645\u06cc\u0646\u0627\u0646 \u0628\u06cc\u0634\u062a\u0631\u06cc \u0646\u0633\u0628\u062a \u0628\u0647 \u0633\u0647 \u06af\u0632\u06cc\u0646\u0647\u0654 \u062f\u06cc\u06af\u0631 \u0642\u0627\u0628\u0644 \u0627\u0633\u062a\u0641\u0627\u062f\u0647 \u0627\u0633\u062a.",
   "interpretation": "\u0627\u0631\u06cc\u062a\u0631\u0648\u0645\u0627\u06cc\u0633\u06cc\u0646 \u062c\u0632\u0648 \u0645\u0627\u06a9\u0631\u0648\u0644\u06cc\u062f\u0647\u0627\u0633\u062a \u0648 \u062f\u0631 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0646\u0633\u0628\u062a\u0627\u064b \u0628\u06cc\u200c\u062e\u0637\u0631 \u062a\u0644\u0642\u06cc \u0645\u06cc\u200c\u0634\u0648\u062f\u061b \u0633\u06cc\u067e\u0631\u0648\u0641\u0644\u0648\u06a9\u0633\u0627\u0633\u06cc\u0646 (\u0641\u0644\u0648\u0631\u0648\u06a9\u06cc\u0646\u0648\u0644\u0648\u0646) \u0628\u0647\u200c\u062f\u0644\u06cc\u0644 \u062e\u0637\u0631 \u0622\u0633\u06cc\u0628 \u063a\u0636\u0631\u0648\u0641 \u0648 \u0633\u06cc\u0633\u062a\u0645 \u0627\u0633\u06a9\u0644\u062a\u06cc \u0646\u0627\u06a9\u0627\u0631\u0622\u0645\u062f\u061b \u0645\u062a\u0631\u0648\u0646\u06cc\u062f\u0627\u0632\u0648\u0644 \u062f\u0631 \u0633\u0647\u200c\u0645\u0627\u0647\u0647\u0654 \u0627\u0648\u0644 \u0628\u0627 \u0627\u062d\u062a\u06cc\u0627\u0637/\u0645\u062d\u062f\u0648\u062f\u06cc\u062a\u060c \u0627\u0645\u0627 \u0628\u0639\u062f\u0627\u0632 \u06f1\u06f2 \u0647\u0641\u062a\u0647 \u0628\u06cc\u0634\u062a\u0631 \u0627\u0633\u062a\u0641\u0627\u062f\u0647 \u0645\u06cc\u200c\u0634\u0648\u062f\u061b \u062a\u062a\u0631\u0627\u0633\u0627\u06cc\u06a9\u0644\u06cc\u0646 \u0628\u0647\u200c\u062f\u0644\u06cc\u0644 \u0631\u0646\u06af \u062f\u0646\u062f\u0627\u0646 \u0648 \u062a\u0623\u062b\u06cc\u0631 \u0631\u0648\u06cc \u0627\u0633\u062a\u062e\u0648\u0627\u0646 \u0645\u0645\u0646\u0648\u0639 \u0627\u0633\u062a.",
   "reasons": ["\u0627\u0631\u06cc\u062a\u0631\u0648\u0645\u0627\u06cc\u0633\u06cc\u0646 \u062f\u0631 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0646\u0633\u0628\u062a\u0627\u064b \u0628\u06cc\u200c\u062e\u0637\u0631 \u06af\u0632\u0627\u0631\u0634 \u0634\u062f\u0647\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u0633\u06cc\u067e\u0631\u0648\u0641\u0644\u0648\u06a9\u0633\u0627\u0633\u06cc\u0646 \u0628\u0647\u200c\u062f\u0644\u06cc\u0644 \u0622\u0633\u06cc\u0628 \u063a\u0636\u0631\u0648\u0641 \u062f\u0631 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u06a9\u0646\u062a\u0631\u0627\u0646\u062f\u06cc\u06a9\u0647 \u0627\u0633\u062a.", "\u0645\u062a\u0631\u0648\u0646\u06cc\u062f\u0627\u0632\u0648\u0644 \u062f\u0631 \u0633\u0647\u200c\u0645\u0627\u0647\u0647\u0654 \u0627\u0648\u0644 \u0628\u0627 \u0627\u062d\u062a\u06cc\u0627\u0637 \u0647\u0645\u0631\u0627\u0647 \u0627\u0633\u062a.", "\u062a\u062a\u0631\u0627\u0633\u0627\u06cc\u06a9\u0644\u06cc\u0646 \u0628\u0647\u200c\u062f\u0644\u06cc\u0644 \u0627\u062b\u0631 \u0631\u0646\u06af\u06cc \u0648 \u0627\u0633\u06a9\u0644\u062a\u06cc \u062f\u0631 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0645\u0645\u0646\u0648\u0639 \u0627\u0633\u062a."],
  },
  (28, 161): {
   "topic": "placentalSiteTrophoblasticTumor",
   "lead": "\u062a\u0648\u0645\u0648\u0631 \u062a\u0631\u0648\u0641\u0648\u0628\u0644\u0627\u0633\u062a\u06cc\u06a9 \u0645\u062d\u0644 \u062c\u0641\u062a (PSTT) \u0628\u0647\u200c\u062e\u0627\u0637\u0631 \u06a9\u0645\u200c\u067e\u0627\u0633\u062e\u200c\u0628\u0648\u062f\u0646 \u0628\u0647 \u0634\u06cc\u0645\u06cc\u200c\u062f\u0631\u0645\u0627\u0646\u06cc\u060c \u062e\u0637 \u0627\u0648\u0644 \u062f\u0631\u0645\u0627\u0646 \u0628\u0627 \u0647\u06cc\u0633\u062a\u0631\u06a9\u062a\u0648\u0645\u06cc \u0627\u0633\u062a.",
   "interpretation": "\u062a\u0648\u0645\u0648\u0631 \u062a\u0631\u0648\u0641\u0648\u0628\u0644\u0627\u0633\u062a\u06cc\u06a9 \u0645\u062d\u0644 \u062c\u0641\u062a (PSTT) \u0627\u0632 \u062a\u0631\u0648\u0641\u0648\u0628\u0644\u0627\u0633\u062a \u0645\u06cc\u0627\u0646\u06cc \u0645\u0646\u0634\u0623 \u0645\u06cc\u200c\u06af\u06cc\u0631\u062f \u0648 \u0645\u0639\u0645\u0648\u0644\u0627\u064b BHCG \u0646\u0633\u0628\u062a\u0627\u064b \u067e\u0627\u06cc\u06cc\u0646\u06cc \u062f\u0627\u0631\u062f\u061b \u0628\u0647 \u0634\u06cc\u0645\u06cc\u200c\u062f\u0631\u0645\u0627\u0646\u06cc \u067e\u0627\u0633\u062e \u0636\u0639\u06cc\u0641\u06cc \u0645\u06cc\u200c\u062f\u0647\u062f \u0648 \u062f\u0631 \u0628\u06cc\u0645\u0627\u0631\u06cc \u0645\u0648\u0636\u0639\u06cc\u060c \u0647\u06cc\u0633\u062a\u0631\u06a9\u062a\u0648\u0645\u06cc \u062e\u0637 \u0627\u0648\u0644 \u062f\u0631\u0645\u0627\u0646 \u0627\u0633\u062a\u061b \u06a9\u0645\u0648\u062a\u0631\u0627\u067e\u06cc \u062a\u06a9\u200c\u062f\u0627\u0631\u0648\u06cc\u06cc \u06cc\u0627 \u062a\u0631\u06a9\u06cc\u0628\u06cc \u0628\u0631\u0627\u06cc \u0645\u0648\u0627\u0631\u062f \u0645\u062a\u0627\u0633\u062a\u0627\u062a\u06cc\u06a9 \u06cc\u0627 \u0639\u0648\u062f\u06a9\u0646\u0646\u062f\u0647 \u0648 \u0631\u0627\u062f\u06cc\u0648\u062a\u0631\u0627\u067e\u06cc \u0641\u0642\u0637 \u062f\u0631 \u0646\u0642\u0634 \u067e\u0627\u0644\u0627\u06cc\u0634\u06cc \u06cc\u0627 \u067e\u0631\u062e\u0637\u0631 \u0645\u0637\u0631\u062d \u0645\u06cc\u200c\u0634\u0648\u062f.",
   "reasons": ["\u0647\u06cc\u0633\u062a\u0631\u06a9\u062a\u0648\u0645\u06cc \u062e\u0637 \u0627\u0648\u0644 \u062f\u0631\u0645\u0627\u0646 PSTT \u0645\u0648\u0636\u0639\u06cc \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u06a9\u0645\u0648\u062a\u0631\u0627\u067e\u06cc \u062a\u06a9\u200c\u062f\u0627\u0631\u0648\u06cc\u06cc \u062f\u0631 PSTT \u067e\u0627\u0633\u062e \u0636\u0639\u06cc\u0641\u06cc \u062f\u0627\u0631\u062f.", "\u06a9\u0645\u0648\u062a\u0631\u0627\u067e\u06cc \u062a\u0631\u06a9\u06cc\u0628\u06cc \u0641\u0642\u0637 \u062f\u0631 \u0645\u0648\u0627\u0631\u062f \u0645\u062a\u0627\u0633\u062a\u0627\u062a\u06cc\u06a9 \u06cc\u0627 \u0645\u0642\u0627\u0648\u0645 \u0645\u0646\u0627\u0633\u0628 \u0627\u0633\u062a.", "\u0631\u0627\u062f\u06cc\u0648\u062a\u0631\u0627\u067e\u06cc \u062f\u0631 PSTT \u0628\u0647\u200c\u0639\u0646\u0648\u0627\u0646 \u062e\u0637 \u0627\u0648\u0644 \u062f\u0631\u0645\u0627\u0646 \u0628\u0647\u200c\u06a9\u0627\u0631 \u0646\u0645\u06cc\u200c\u0631\u0648\u062f."],
  },
  (28, 162): {
   "topic": "abortionTypes",
   "lead": "\u062a\u0631\u0634\u062d \u0622\u0628\u06a9\u06cc\u060c \u0644\u06a9\u0647\u200c\u0628\u06cc\u0646\u06cc \u0648 \u0633\u0631\u0648\u06cc\u06a9\u0633 \u062f\u0648 \u0633\u0627\u0646\u062a\u06cc\u200c\u0645\u062a\u0631\u06cc \u0628\u0627\u0632 \u062f\u0631 \u0647\u0641\u062a\u0647\u0654 \u067e\u0627\u0646\u0632\u062f\u0647\u0645\u060c \u062a\u0639\u0631\u06cc\u0641 \u0633\u0642\u0637 \u0627\u062c\u062a\u0646\u0627\u0628\u200c\u0646\u0627\u067e\u0630\u06cc\u0631 \u0627\u0633\u062a.",
   "interpretation": "\u0633\u0642\u0637 \u0627\u062c\u062a\u0646\u0627\u0628\u200c\u0646\u0627\u067e\u0630\u06cc\u0631 \u06cc\u0639\u0646\u06cc \u062e\u0648\u0646\u200c\u0631\u06cc\u0632\u06cc \u06cc\u0627 \u062a\u0631\u0634\u062d \u0647\u0645\u0631\u0627\u0647 \u0628\u0627\u0632\u0634\u062f\u0646 \u0633\u0631\u0648\u06cc\u06a9\u0633 \u0628\u062f\u0648\u0646 \u0639\u0628\u0648\u0631 \u0645\u062d\u0635\u0648\u0644\u0627\u062a \u0628\u0627\u0631\u062f\u0627\u0631\u06cc\u061b \u062f\u0631 \u00ab\u062a\u0647\u062f\u06cc\u062f \u0628\u0647 \u0633\u0642\u0637\u00bb \u0633\u0631\u0648\u06cc\u06a9\u0633 \u0628\u0633\u062a\u0647 \u0627\u0633\u062a\u061b \u062f\u0631 \u00ab\u0633\u0642\u0637 \u06a9\u0627\u0645\u0644\u00bb \u06a9\u0644 \u0628\u0627\u0642\u06cc\u200c\u0645\u0627\u0646\u062f\u0647 \u062e\u0627\u0631\u062c \u0634\u062f\u0647 \u0648 \u0633\u0631\u0648\u06cc\u06a9\u0633 \u0628\u0633\u062a\u0647 \u0645\u06cc\u200c\u0634\u0648\u062f\u061b \u062f\u0631 \u00ab\u0633\u0642\u0637 \u0646\u0627\u0642\u0635\u00bb \u0642\u0633\u0645\u062a\u06cc \u0627\u0632 \u0628\u0627\u0641\u062a \u062e\u0627\u0631\u062c \u0648 \u0642\u0633\u0645\u062a\u06cc \u0628\u0627\u0642\u06cc \u0645\u0627\u0646\u062f\u0647 \u0627\u0633\u062a. \u0628\u0627 \u062a\u0631\u0634\u062d\u200c\u0622\u0628\u06a9\u06cc\u060c \u0644\u06a9\u0647\u200c\u0628\u06cc\u0646\u06cc \u0648 \u062f\u06cc\u0644\u0627\u062a\u0627\u0633\u06cc\u0648\u0646 \u062f\u0648 \u0633\u0627\u0646\u062a\u06cc\u200c\u0645\u062a\u0631\u06cc \u0648 \u0627\u062f\u0627\u0645\u0647\u0654 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc\u060c \u0627\u062c\u062a\u0646\u0627\u0628\u200c\u0646\u0627\u067e\u0630\u06cc\u0631 \u0645\u0637\u0631\u062d \u0627\u0633\u062a.",
   "reasons": ["\u062a\u0647\u062f\u06cc\u062f \u0628\u0647 \u0633\u0642\u0637 \u0628\u0627 \u0633\u0631\u0648\u06cc\u06a9\u0633 \u0628\u0633\u062a\u0647 \u062a\u0639\u0631\u06cc\u0641 \u0645\u06cc\u200c\u0634\u0648\u062f \u0646\u0647 \u0628\u0627\u0632.", "\u0633\u0642\u0637 \u06a9\u0627\u0645\u0644 \u0628\u0627 \u0639\u0628\u0648\u0631 \u06a9\u0627\u0645\u0644 \u0645\u062d\u0635\u0648\u0644\u0627\u062a \u062a\u0639\u0631\u06cc\u0641 \u0645\u06cc\u200c\u0634\u0648\u062f.", "\u0633\u0631\u0648\u06cc\u06a9\u0633 \u0628\u0627\u0632 \u0628\u062f\u0648\u0646 \u0639\u0628\u0648\u0631 \u0645\u062d\u0635\u0648\u0644\u0627\u062a \u06cc\u0639\u0646\u06cc \u0627\u062c\u062a\u0646\u0627\u0628\u200c\u0646\u0627\u067e\u0630\u06cc\u0631\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u0633\u0642\u0637 \u0646\u0627\u0642\u0635 \u0628\u0627 \u0628\u0627\u0642\u06cc\u200c\u0645\u0627\u0646\u062f\u0646 \u0642\u0633\u0645\u062a\u06cc \u0627\u0632 \u0628\u0627\u0641\u062a \u067e\u0633 \u0627\u0632 \u062e\u0631\u0648\u062c \u062a\u0639\u0631\u06cc\u0641 \u0645\u06cc\u200c\u0634\u0648\u062f."],
  },
  (28, 163): {
   "topic": "varicellaExposureFirst",
   "lead": "\u0627\u0648\u0644\u06cc\u0646 \u0627\u0642\u062f\u0627\u0645 \u062f\u0631 \u062a\u0645\u0627\u0633 \u0628\u0627\u0631\u062f\u0627\u0631 \u0628\u062f\u0648\u0646 \u0633\u0627\u0628\u0642\u0647\u0654 \u0622\u0628\u0644\u0647\u0654 \u0645\u0631\u063a\u0627\u0646\u060c \u0627\u0646\u062f\u0627\u0632\u0647\u200c\u06af\u06cc\u0631\u06cc \u0622\u0646\u062a\u06cc\u200c\u0628\u0627\u062f\u06cc \u0636\u062f \u0648\u0627\u0631\u06cc\u0633\u0644\u0627 \u0627\u0633\u062a.",
   "interpretation": "\u067e\u06cc\u0634 \u0627\u0632 \u0647\u0631 \u062a\u0635\u0645\u06cc\u0645 (\u062a\u062c\u0648\u06cc\u0632 \u0627\u06cc\u0645\u0648\u0646\u0648\u06af\u0644\u0648\u0628\u0648\u0644\u06cc\u0646 \u0648\u0627\u0631\u06cc\u0633\u0644\u0627 \u06cc\u0627 \u067e\u06cc\u06af\u06cc\u0631\u06cc)\u060c \u062a\u0639\u06cc\u06cc\u0646 \u0648\u0636\u0639\u06cc\u062a \u0627\u06cc\u0645\u0646\u06cc \u0636\u0631\u0648\u0631\u06cc \u0627\u0633\u062a: \u0627\u06af\u0631 IgG \u0645\u062b\u0628\u062a \u0628\u0627\u0634\u062f \u0645\u0627\u062f\u0631 \u0627\u06cc\u0645\u0646 \u0627\u0633\u062a \u0648 \u0627\u0642\u062f\u0627\u0645\u06cc \u0644\u0627\u0632\u0645 \u0646\u06cc\u0633\u062a\u061b \u0627\u06af\u0631 \u0645\u0646\u0641\u06cc \u0628\u0627\u0634\u062f\u060c \u0627\u06cc\u0645\u0648\u0646\u0648\u06af\u0644\u0648\u0628\u0648\u0644\u06cc\u0646 \u062a\u0627 \u06f9\u06f6 \u0633\u0627\u0639\u062a \u067e\u0633 \u0627\u0632 \u062a\u0645\u0627\u0633 \u062a\u062c\u0648\u06cc\u0632 \u0645\u06cc\u200c\u0634\u0648\u062f \u0648 \u062f\u0631 \u0635\u0648\u0631\u062a \u0627\u0628\u062a\u0644\u0627\u060c \u0622\u0633\u06cc\u06a9\u0644\u0648\u0648\u06cc\u0631 \u062f\u0631 \u0646\u0638\u0631 \u06af\u0631\u0641\u062a\u0647 \u0645\u06cc\u200c\u0634\u0648\u062f\u061b \u0633\u0648\u0646\u0648\u06af\u0631\u0627\u0641\u06cc \u0622\u0646\u0648\u0645\u0627\u0644\u06cc \u062f\u0631 \u0627\u06cc\u0646 \u0645\u0631\u062d\u0644\u0647 \u06a9\u0645\u06a9\u200c\u06a9\u0646\u0646\u062f\u0647 \u0646\u06cc\u0633\u062a.",
   "reasons": ["\u0627\u0646\u062f\u0627\u0632\u0647\u200c\u06af\u06cc\u0631\u06cc IgG \u0648\u0627\u0631\u06cc\u0633\u0644\u0627 \u06af\u0627\u0645 \u0627\u0648\u0644 \u0645\u0646\u0637\u0642\u06cc \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u0627\u06cc\u0645\u0648\u0646\u0648\u06af\u0644\u0648\u0628\u0648\u0644\u06cc\u0646 \u0641\u0642\u0637 \u062f\u0631 \u0635\u0648\u0631\u062a IgG \u0645\u0646\u0641\u06cc \u0648 \u062a\u0627 \u06f9\u06f6 \u0633\u0627\u0639\u062a \u062f\u0627\u062f\u0647 \u0645\u06cc\u200c\u0634\u0648\u062f.", "\u0622\u0633\u06cc\u06a9\u0644\u0648\u0648\u06cc\u0631 \u062e\u0648\u0631\u0627\u06a9\u06cc \u062f\u0631 \u0635\u0648\u0631\u062a \u0627\u0628\u062a\u0644\u0627\u06cc \u0642\u0637\u0639\u06cc \u0645\u0627\u062f\u0631 \u062a\u062c\u0648\u06cc\u0632 \u0645\u06cc\u200c\u0634\u0648\u062f.", "\u0633\u0648\u0646\u0648\u06af\u0631\u0627\u0641\u06cc \u0627\u0646\u0648\u0645\u0627\u0644\u06cc \u062f\u0631 \u0627\u06cc\u0646 \u0645\u0631\u062d\u0644\u0647\u0654 \u062a\u0645\u0627\u0633 \u0627\u0648\u0644\u06cc\u0647 \u06a9\u0645\u06a9\u06cc \u0646\u0645\u06cc\u200c\u06a9\u0646\u062f."],
  },
  (28, 164): {
   "topic": "octInterpretation",
   "lead": "\u0648\u062c\u0648\u062f \u0627\u0641\u062a \u062f\u06cc\u0631\u0631\u0633 \u067e\u0633 \u0627\u0632 \u06f3 \u0627\u0646\u0642\u0628\u0627\u0636 (\u2265\u06f5\u06f0\u066a \u0627\u0646\u0642\u0628\u0627\u0636\u200c\u0647\u0627) \u062f\u0631 OCT\u060c \u0646\u062a\u06cc\u062c\u0647\u0654 \u0645\u062b\u0628\u062a \u0627\u0633\u062a.",
   "interpretation": "OCT/CST \u00ab\u0645\u062b\u0628\u062a\u00bb = \u0627\u0641\u062a \u062f\u06cc\u0631\u0631\u0633 \u06cc\u0627 \u0645\u062a\u063a\u06cc\u0631 \u067e\u0633 \u0627\u0632 \u062d\u062f\u0627\u0642\u0644 \u0646\u06cc\u0645\u06cc \u0627\u0632 \u0627\u0646\u0642\u0628\u0627\u0636\u200c\u0647\u0627\u061b \u00ab\u0645\u0646\u0641\u06cc\u00bb = \u0639\u062f\u0645 \u0627\u0641\u062a\u061b \u00ab\u0645\u0634\u06a9\u0648\u06a9/\u0645\u0634\u06a9\u0648\u06a9 \u0645\u062b\u0628\u062a\u00bb = \u0627\u0641\u062a \u06a9\u0645\u062a\u0631 \u0627\u0632 \u0646\u06cc\u0645\u06cc \u0627\u0632 \u0627\u0646\u0642\u0628\u0627\u0636\u200c\u0647\u0627\u061b \u00ab\u0631\u0636\u0627\u06cc\u062a\u200c\u0628\u062e\u0634 \u0646\u06cc\u0633\u062a\u00bb = \u06a9\u0641\u0627\u06cc\u062a \u0627\u0646\u0642\u0628\u0627\u0636/\u0646\u0648\u0627\u0631 \u0646\u0627\u0645\u0646\u0627\u0633\u0628. \u062f\u0631 \u0627\u06cc\u0646\u062c\u0627 \u06f3 \u0627\u0646\u0642\u0628\u0627\u0636 \u0627\u0632 \u06f6 (\u06f5\u06f0\u066a) \u0647\u0645\u0631\u0627\u0647 \u0627\u0641\u062a \u062f\u06cc\u0631\u0631\u0633 \u062b\u0628\u062a \u0634\u062f\u0647 \u21d2 \u0645\u062b\u0628\u062a.",
   "reasons": ["\u0627\u0641\u062a \u067e\u0633 \u0627\u0632 \u0646\u06cc\u0645\u06cc \u0627\u0632 \u0627\u0646\u0642\u0628\u0627\u0636\u200c\u0647\u0627 \u062a\u0639\u0631\u06cc\u0641 \u062a\u0633\u062a \u0645\u062b\u0628\u062a \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u0645\u0646\u0641\u06cc \u0628\u0627 \u0633\u0627\u0644\u0645\u200c\u0628\u0648\u062f\u0646 FHR \u067e\u0633 \u0627\u0632 \u0627\u0646\u0642\u0628\u0627\u0636\u200c\u0647\u0627 \u062a\u0639\u0631\u06cc\u0641 \u0645\u06cc\u200c\u0634\u0648\u062f.", "\u0645\u0634\u06a9\u0648\u06a9 \u0648\u0642\u062a\u06cc \u0627\u0641\u062a \u06a9\u0645\u062a\u0631 \u0627\u0632 \u0646\u06cc\u0645\u06cc \u0627\u0632 \u0627\u0646\u0642\u0628\u0627\u0636\u200c\u0647\u0627 \u062b\u0628\u062a \u0634\u0648\u062f.", "\u0646\u0627\u0631\u0633\u0627\u06cc\u06cc \u062a\u0633\u062a \u0648\u0642\u062a\u06cc \u0627\u0646\u0642\u0628\u0627\u0636 \u06a9\u0627\u0641\u06cc \u0627\u06cc\u062c\u0627\u062f \u0646\u0634\u062f\u0647 \u0628\u0627\u0634\u062f."],
  },
  (28, 165): {
   "topic": "apgarScoreCalc",
   "lead": "\u0628\u0627 \u0645\u062d\u0627\u0633\u0628\u0647\u0654 \u0627\u062c\u0632\u0627\u06cc \u0622\u067e\u06af\u0627\u0631 (\u0631\u0646\u06af\u060c \u0646\u0628\u0636\u060c \u062a\u0648\u0646\u060c \u062a\u0646\u0641\u0633\u060c \u0631\u0641\u0644\u06a9\u0633) \u0627\u0645\u062a\u06cc\u0627\u0632 \u0645\u062c\u0645\u0648\u0639 \u0628\u0631\u0627\u0628\u0631 \u06f7 \u0628\u0647\u200c\u062f\u0633\u062a \u0645\u06cc\u200c\u0622\u06cc\u062f.",
   "interpretation": "\u0631\u0646\u06af: \u0628\u062f\u0646 \u0635\u0648\u0631\u062a\u06cc \u0648 \u0627\u0646\u062a\u0647\u0627 \u0622\u0628\u06cc = \u06f1\u061b \u0636\u0631\u0628\u0627\u0646 \u0642\u0644\u0628 \u06f1\u06f0\u06f0 \u06cc\u0627 \u0628\u06cc\u0634\u062a\u0631 = \u06f2\u061b \u062a\u0648\u0646 \u0639\u0636\u0644\u0627\u0646\u06cc \u0628\u0627 \u0641\u0644\u06a9\u0633\u06cc\u0648\u0646 \u0646\u0633\u0628\u06cc = \u06f1\u061b \u062a\u0646\u0641\u0633 \u0646\u0627\u0645\u0646\u0638\u0645 = \u06f1\u061b \u0631\u0641\u0644\u06a9\u0633 \u0628\u0627 \u0639\u0642\u0628\u200c\u0632\u062f\u0646/\u06af\u0631\u06cc\u0647\u0654 \u0642\u0648\u06cc = \u06f2. \u0645\u062c\u0645\u0648\u0639 = \u06f7. \u0628\u0646\u0627\u0628\u0631\u0627\u06cc\u0646 \u0622\u067e\u06af\u0627\u0631 \u0646\u0648\u0632\u0627\u062f \u06f7 \u0627\u0633\u062a.",
   "reasons": ["\u0627\u0645\u062a\u06cc\u0627\u0632 \u06f4 \u0628\u0627 \u062d\u0641\u0638 \u0636\u0631\u0628\u0627\u0646 \u0642\u0644\u0628 \u0628\u0627\u0644\u0627\u06cc \u06f1\u06f0\u06f0 \u0633\u0627\u0632\u06af\u0627\u0631 \u0646\u06cc\u0633\u062a.", "\u0627\u0645\u062a\u06cc\u0627\u0632 \u06f5 \u0628\u062f\u0648\u0646 \u0644\u062d\u0627\u0638 \u06a9\u0631\u062f\u0646 \u0631\u0641\u0644\u06a9\u0633 \u0642\u0648\u06cc \u0645\u062d\u0627\u0633\u0628\u0647 \u0634\u062f\u0647 \u0627\u0633\u062a.", "\u0627\u0645\u062a\u06cc\u0627\u0632 \u06f6 \u0641\u0644\u06a9\u0633\u06cc\u0648\u0646 \u0646\u0633\u0628\u06cc \u0631\u0627 \u0635\u0641\u0631 \u062f\u0631 \u0646\u0638\u0631 \u06af\u0631\u0641\u062a\u0647 \u0627\u0633\u062a.", "\u0645\u062c\u0645\u0648\u0639 \u0627\u062c\u0632\u0627 \u0628\u0631\u0627\u0628\u0631 \u06f7 \u0645\u062d\u0627\u0633\u0628\u0647 \u0645\u06cc\u200c\u0634\u0648\u062f\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d."],
  },
  (28, 166): {
   "topic": "sfhSmall",
   "lead": "\u062f\u0631 \u0647\u0641\u062a\u0647\u0654 \u06f3\u06f0\u060c \u0627\u0631\u062a\u0641\u0627\u0639 \u0631\u062d\u0645 \u06f2\u06f6 \u0633\u0627\u0646\u062a\u06cc\u200c\u0645\u062a\u0631 (\u0628\u06cc\u0634 \u0627\u0632 \u06f3 \u0633\u0627\u0646\u062a\u06cc\u200c\u0645\u062a\u0631 \u06a9\u0645\u062a\u0631 \u0627\u0632 \u0633\u0646 \u062d\u0627\u0645\u0644\u06af\u06cc) \u0646\u0634\u0627\u0646\u0647\u0654 \u0627\u062d\u062a\u0645\u0627\u0644 IUGR \u0627\u0633\u062a \u0648 \u0633\u0648\u0646\u0648\u06af\u0631\u0627\u0641\u06cc \u062f\u0631\u062e\u0648\u0627\u0633\u062a \u0645\u06cc\u200c\u0634\u0648\u062f.",
   "interpretation": "\u062f\u0631 \u0642\u0627\u0639\u062f\u0647\u0654 \u062a\u0642\u0631\u06cc\u0628\u06cc\u060c \u0627\u0631\u062a\u0641\u0627\u0639 \u0631\u062d\u0645 (\u0633\u0627\u0646\u062a\u06cc\u200c\u0645\u062a\u0631) \u0628\u0627 \u0633\u0646 \u062d\u0627\u0645\u0644\u06af\u06cc (\u0647\u0641\u062a\u0647) \u062a\u0642\u0631\u06cc\u0628\u0627\u064b \u0628\u0631\u0627\u0628\u0631 \u0627\u0633\u062a\u061b \u0641\u0627\u0635\u0644\u0647\u0654 \u0628\u06cc\u0634 \u0627\u0632 \u06f3 \u0633\u0627\u0646\u062a\u06cc\u200c\u0645\u062a\u0631 \u062f\u0631 \u0647\u0641\u062a\u0647\u0654 \u06f3\u06f0 \u0646\u0634\u0627\u0646\u0647\u0654 \u0645\u06cc\u0632\u0627\u0646 \u067e\u0627\u06cc\u06cc\u0646 \u0645\u0627\u06cc\u0639 \u06cc\u0627 \u06a9\u0645\u200c\u0631\u0634\u062f\u06cc \u062c\u0646\u06cc\u0646 \u0627\u0633\u062a. \u06af\u0627\u0645 \u0645\u0646\u0627\u0633\u0628\u060c \u062f\u0631\u062e\u0648\u0627\u0633\u062a \u0633\u0648\u0646\u0648\u06af\u0631\u0627\u0641\u06cc \u0628\u0631\u0627\u06cc \u0627\u0631\u0632\u06cc\u0627\u0628\u06cc \u0631\u0634\u062f\u060c \u0645\u0627\u06cc\u0639 \u0622\u0645\u0646\u06cc\u0648\u062a\u06cc\u06a9 \u0648 \u062f\u0627\u067e\u0644\u0631 \u0627\u0633\u062a\u061b \u0635\u0631\u0641 \u067e\u06cc\u06af\u06cc\u0631\u06cc \u0628\u062f\u0648\u0646 \u0628\u0631\u0631\u0633\u06cc \u0645\u0646\u0627\u0633\u0628 \u0646\u06cc\u0633\u062a \u0648 \u062e\u062a\u0645 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u06cc\u0627 NST \u0628\u062f\u0648\u0646 \u062a\u0623\u06cc\u06cc\u062f \u0627\u0648\u0644\u06cc\u0647 \u062a\u0635\u0645\u06cc\u0645 \u0639\u062c\u0648\u0644\u0627\u0646\u0647 \u0627\u0633\u062a.",
   "reasons": ["\u0627\u0646\u06a9\u0627\u0631 \u0645\u0634\u06a9\u0644 \u0648 \u067e\u06cc\u06af\u06cc\u0631\u06cc \u062f\u0648 \u0647\u0641\u062a\u0647 \u0628\u0639\u062f\u060c \u0631\u06cc\u0633\u06a9 \u063a\u0631\u0628\u0627\u0644\u06af\u0631\u06cc \u0627\u0632 \u062f\u0633\u062a\u200c\u0631\u0641\u062a\u0647 \u0627\u0633\u062a.", "\u0633\u0648\u0646\u0648\u06af\u0631\u0627\u0641\u06cc \u0628\u0631\u0627\u06cc \u0627\u0631\u0632\u06cc\u0627\u0628\u06cc \u0631\u0634\u062f \u0648 \u0634\u0627\u062e\u0635\u200c\u0647\u0627\u06cc \u0647\u0645\u0631\u0627\u0647 \u0636\u0631\u0648\u0631\u06cc \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u062e\u062a\u0645 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0628\u062f\u0648\u0646 \u062a\u0623\u06cc\u06cc\u062f IUGR \u0628\u0631 \u067e\u0627\u06cc\u0647\u0654 \u0627\u0631\u062a\u0641\u0627\u0639 \u0633\u0645\u0641\u06cc\u0632 \u062a\u0646\u0647\u0627 \u0627\u0646\u062c\u0627\u0645 \u0646\u0645\u06cc\u200c\u0634\u0648\u062f.", "NST \u0628\u0647\u200c\u062a\u0646\u0647\u0627\u06cc\u06cc \u0642\u0628\u0644 \u0627\u0632 \u0633\u0648\u0646\u0648\u06af\u0631\u0627\u0641\u06cc \u0628\u062f\u0648\u0646 \u06cc\u0627\u0641\u062a\u0647\u0654 \u0627\u0636\u0627\u0641\u06cc \u0636\u0631\u0648\u0631\u06cc \u0646\u06cc\u0633\u062a."],
  },
  (28, 167): {
   "topic": "gonadalFailureKaryotype",
   "lead": "\u062f\u0631 \u0622\u0645\u0646\u0648\u0631\u0647\u0654 \u0627\u0648\u0644\u06cc\u0647 \u0628\u0627 \u0639\u062f\u0645 \u0639\u0644\u0627\u0626\u0645 \u0628\u0644\u0648\u063a + FSH \u0628\u0627\u0644\u0627\u060c \u06a9\u0627\u0631\u06cc\u0648\u062a\u06cc\u067e \u0628\u0631\u0627\u06cc \u0627\u062e\u062a\u0644\u0627\u0644\u0627\u062a \u06af\u0646\u0627\u062f\u06cc (\u0645\u062b\u0644 \u062a\u0648\u0631\u0646\u0631) \u06af\u0627\u0632 \u0627\u0648\u0644 \u0627\u0633\u062a.",
   "interpretation": "\u062f\u0631 \u062f\u062e\u062a\u0631 \u06f1\u06f7 \u0633\u0627\u0644\u0647 \u0628\u0627 \u0639\u062f\u0645 \u0628\u0631\u0648\u0632 \u0639\u0644\u0627\u0626\u0645 \u0628\u0644\u0648\u063a\u060c FSH \u0628\u0627\u0644\u0627 (\u0627\u0644\u06af\u0648\u06cc \u0647\u0627\u06cc\u067e\u0631\u06af\u0646\u0627\u062f\u0648\u062a\u0631\u0648\u067e\u06cc\u06a9) \u0646\u0634\u0627\u0646\u0647\u0654 \u0646\u0627\u0631\u0633\u0627\u06cc\u06cc \u0627\u0648\u0644\u06cc\u0647\u0654 \u062a\u062e\u0645\u062f\u0627\u0646 \u0627\u0633\u062a\u061b \u06a9\u0627\u0631\u06cc\u0648\u062a\u06cc\u067e \u0628\u0631\u0627\u06cc \u0627\u0641\u062a\u0631\u0627\u0642 \u0633\u0646\u062f\u0631\u0645 \u062a\u0631\u0646\u0631 \u06cc\u0627 \u062f\u06cc\u0633\u200c\u0698\u0646\u0632\u06cc \u06af\u0646\u0627\u062f\u0647\u0627 \u06af\u0627\u0645 \u0627\u0648\u0644 \u0627\u0633\u062a. MRI \u0647\u06cc\u067e\u0648\u0641\u06cc\u0632 \u0628\u0631\u0627\u06cc \u062d\u0627\u0644\u062a \u06a9\u0645\u200c\u06af\u0646\u0627\u062f\u0648\u062a\u0631\u0648\u067e\u06cc\u06a9 \u0648 MRI \u0644\u06af\u0646 \u0628\u0631\u0627\u06cc \u0646\u0627\u0647\u0646\u062c\u0627\u0631\u06cc\u200c\u0647\u0627\u06cc \u0631\u062d\u0645\u06cc/\u0644\u0648\u0644\u0647\u200c\u0627\u06cc\u060c \u0648 \u0627\u062a\u0648\u0622\u0646\u062a\u06cc\u200c\u0628\u0627\u062f\u06cc\u200c\u0647\u0627 \u062f\u0631 \u0633\u0646\u06cc\u0646 \u0628\u0627\u0644\u0627\u062a\u0631 \u0648 \u0628\u062f\u0648\u0646 \u0631\u06cc\u0634\u0647\u0654 \u06a9\u0631\u0648\u0645\u0648\u0632\u0648\u0645\u06cc \u062f\u0631 \u0646\u0638\u0631 \u06af\u0631\u0641\u062a\u0647 \u0645\u06cc\u200c\u0634\u0648\u062f.",
   "reasons": ["MRI \u0647\u06cc\u067e\u0648\u0641\u06cc\u0632 \u062f\u0631 \u0627\u0644\u06af\u0648\u06cc \u06a9\u0645\u200c\u06af\u0646\u0627\u062f\u0648\u062a\u0631\u0648\u067e\u06cc\u06a9 (FSH \u067e\u0627\u06cc\u06cc\u0646) \u0628\u0631\u0631\u0633\u06cc \u0645\u06cc\u200c\u0634\u0648\u062f.", "\u06a9\u0627\u0631\u06cc\u0648\u062a\u06cc\u067e \u062f\u0631 \u0633\u0646\u062f\u0631\u0645 \u062a\u0631\u0646\u0631/\u062f\u06cc\u0633\u200c\u0698\u0646\u0632\u06cc \u06af\u0646\u0627\u062f\u0647\u0627 \u06af\u0627\u0645 \u0627\u0648\u0644 \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u0627\u062a\u0648\u0622\u0646\u062a\u06cc\u200c\u0628\u0627\u062f\u06cc\u200c\u0647\u0627 \u0628\u06cc\u0634\u062a\u0631 \u062f\u0631 \u0646\u0627\u0631\u0633\u0627\u06cc\u06cc \u0632\u0648\u062f\u0631\u0633 \u062a\u062e\u0645\u062f\u0627\u0646 \u0648 \u0628\u062f\u0648\u0646 \u0639\u0644\u062a \u06a9\u0631\u0648\u0645\u0648\u0632\u0648\u0645\u06cc \u0645\u0637\u0631\u062d\u200c\u0627\u0646\u062f.", "MRI \u0644\u06af\u0646 \u0628\u0631\u0627\u06cc \u0646\u0627\u0647\u0646\u062c\u0627\u0631\u06cc\u200c\u0647\u0627\u06cc \u0631\u062d\u0645 \u0648 \u0644\u0648\u0644\u0647 \u0628\u0647\u200c\u06a9\u0627\u0631 \u0645\u06cc\u200c\u0631\u0648\u062f \u0646\u0647 \u0646\u062e\u0633\u062a."],
  },
  (28, 168): {
   "topic": "montevideoUnits",
   "lead": "\u0648\u0627\u062d\u062f \u0645\u0648\u0646\u062a\u0647\u200c\u0648\u06cc\u062f\u0626\u0648 = \u062a\u0639\u062f\u0627\u062f \u0627\u0646\u0642\u0628\u0627\u0636 \u00d7 \u0627\u062e\u062a\u0644\u0627\u0641 \u0627\u0632 \u062e\u0637 \u067e\u0627\u06cc\u0647 (\u0645\u06cc\u0644\u06cc\u200c\u0645\u062a\u0631 \u062c\u06cc\u0648\u0647) \u0628\u0648\u062f\u0647\u060c \u062f\u0631 \u06f1\u06f0 \u062f\u0642\u06cc\u0642\u0647\u061b \u0627\u06cc\u0646\u062c\u0627 \u06f4 \u0627\u0646\u0642\u0628\u0627\u0636 \u00d7 \u06f5\u06f0 = \u06f2\u06f0\u06f0 \u0648\u0627\u062d\u062f.",
   "interpretation": "\u0648\u0627\u062d\u062f \u0645\u0648\u0646\u062a\u0647\u200c\u0648\u06cc\u062f\u0626\u0648 \u0627\u0632 \u062d\u0627\u0635\u0644\u200c\u0636\u0631\u0628 \u062a\u0639\u062f\u0627\u062f \u0627\u0646\u0642\u0628\u0627\u0636\u0627\u062a \u062f\u0631 \u06f1\u06f0 \u062f\u0642\u06cc\u0642\u0647 \u062f\u0631 \u0645\u06cc\u0632\u0627\u0646 \u0627\u0641\u0632\u0627\u06cc\u0634 \u0641\u0634\u0627\u0631 \u0647\u0631 \u0627\u0646\u0642\u0628\u0627\u0636 \u0646\u0633\u0628\u062a \u0628\u0647 \u062e\u0637 \u067e\u0627\u06cc\u0647 (\u0645\u06cc\u0644\u06cc\u200c\u0645\u062a\u0631 \u062c\u06cc\u0648\u0647) \u0645\u062d\u0627\u0633\u0628\u0647 \u0645\u06cc\u200c\u0634\u0648\u062f\u061b \u06f4 \u0627\u0646\u0642\u0628\u0627\u0636 \u0647\u0631\u06a9\u062f\u0627\u0645 \u06f5\u06f0 \u0645\u06cc\u0644\u06cc\u200c\u0645\u062a\u0631 \u062c\u06cc\u0648\u0647 \u0628\u0627\u0644\u0627\u06cc \u062e\u0637 \u067e\u0627\u06cc\u0647 = \u06f2\u06f0\u06f0 \u0648\u0627\u062d\u062f. \u0645\u0642\u0627\u062f\u06cc\u0631 \u06f1\u06f5\u06f0 \u0648 \u06f1\u06f8\u06f0 \u0648 \u06f2\u06f4\u06f0 \u0628\u0627 \u0627\u06cc\u0646 \u0645\u062d\u0627\u0633\u0628\u0647 \u0633\u0627\u0632\u06af\u0627\u0631 \u0646\u06cc\u0633\u062a\u0646\u062f.",
   "reasons": ["\u06f1\u06f5\u06f0 \u0648\u0627\u062d\u062f \u0633\u0627\u0632\u06af\u0627\u0631 \u0628\u0627 \u0645\u062d\u0627\u0633\u0628\u0647\u0654 \u06f4 \u0627\u0646\u0642\u0628\u0627\u0636 \u00d7 \u06f5\u06f0 \u0646\u06cc\u0633\u062a.", "\u06f2\u06f0\u06f0 \u0648\u0627\u062d\u062f \u062f\u0642\u06cc\u0642\u0627\u064b \u062d\u0627\u0635\u0644 \u06f4 \u0627\u0646\u0642\u0628\u0627\u0636 \u00d7 \u06f5\u06f0 \u0645\u06cc\u0644\u06cc\u200c\u0645\u062a\u0631 \u062c\u06cc\u0648\u0647 \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u06f1\u06f8\u06f0 \u0648\u0627\u062d\u062f \u0628\u0627 \u0641\u0631\u0636 \u0645\u06cc\u0627\u0646\u06af\u06cc\u0646 \u06f4\u06f5 \u0633\u0627\u0632\u06af\u0627\u0631 \u0627\u0633\u062a \u06a9\u0647 \u062f\u0631 \u0633\u0624\u0627\u0644 \u0646\u06cc\u0627\u0645\u062f\u0647.", "\u06f2\u06f4\u06f0 \u0648\u0627\u062d\u062f \u0646\u06cc\u0627\u0632\u0645\u0646\u062f \u062a\u0639\u062f\u0627\u062f \u0627\u0646\u0642\u0628\u0627\u0636 \u0628\u06cc\u0634 \u0627\u0632 \u0686\u0647\u0627\u0631 \u062f\u0631 \u06f1\u06f0 \u062f\u0642\u06cc\u0642\u0647 \u0627\u0633\u062a."],
  },
  (28, 169): {
   "topic": "salineSonohystFocal",
   "lead": "\u0646\u0627\u0645\u0646\u0638\u0645\u06cc \u0648 \u0639\u062f\u0645 \u062a\u0642\u0627\u0631\u0646 \u0622\u0646\u062f\u0648\u0645\u062a\u0631 \u062f\u0631 \u0633\u0648\u0646\u0648\u0647\u06cc\u0633\u062a\u0631\u0648\u06af\u0631\u0627\u0641\u06cc\u060c \u0627\u062d\u062a\u0645\u0627\u0644 \u0636\u0627\u06cc\u0639\u0647\u0654 \u06a9\u0627\u0646\u0648\u0646\u06cc \u0631\u0627 \u0628\u0627\u0644\u0627 \u0645\u06cc\u200c\u0628\u0631\u062f \u0648 \u0647\u06cc\u0633\u062a\u0631\u0648\u0633\u06a9\u0648\u067e\u06cc \u0628\u0647\u062a\u0631\u06cc\u0646 \u06af\u0627\u0645 \u0628\u0639\u062f\u06cc \u0627\u0633\u062a.",
   "interpretation": "\u0628\u0627 \u0633\u0648\u0646\u0648\u0647\u06cc\u0633\u062a\u0631\u0648\u06af\u0631\u0627\u0641\u06cc \u0633\u0627\u0644\u06cc\u0646\u06cc\u060c \u062f\u06cc\u062f\u0647 \u0634\u062f\u0646 \u0622\u0646\u062f\u0648\u0645\u062a\u0631 \u0646\u0627\u0645\u0646\u0638\u0645 \u0648 \u0622\u0633\u06cc\u0645\u062a\u0631\u06cc\u06a9 (\u06f1\u06f2 \u0645\u06cc\u0644\u06cc\u200c\u0645\u062a\u0631 \u062f\u0631 \u0641\u0648\u0646\u062f\u0648\u0633 \u062f\u0631 \u0628\u0631\u0627\u0628\u0631 \u06f6 \u0645\u06cc\u0644\u06cc\u200c\u0645\u062a\u0631 \u062f\u0631 \u0642\u0633\u0645\u062a \u0645\u06cc\u0627\u0646\u06cc) \u0627\u062d\u062a\u0645\u0627\u0644 \u067e\u0648\u0644\u06cc\u067e \u06cc\u0627 \u0647\u0627\u06cc\u067e\u0631\u067e\u0644\u0627\u0632\u06cc \u06a9\u0627\u0646\u0648\u0646\u06cc \u0631\u0627 \u0645\u0637\u0631\u062d \u0645\u06cc\u200c\u06a9\u0646\u062f\u061b \u0647\u06cc\u0633\u062a\u0631\u0648\u0633\u06a9\u0648\u067e\u06cc \u0627\u0645\u06a9\u0627\u0646 \u062f\u06cc\u062f \u0645\u0633\u062a\u0642\u06cc\u0645 \u0648 \u0628\u0631\u062f\u0627\u0634\u062a \u0647\u062f\u0641\u200c\u062f\u0627\u0631 \u0631\u0627 \u0641\u0631\u0627\u0647\u0645 \u0645\u06cc\u200c\u06a9\u0646\u062f. \u06a9\u0648\u0631\u062a\u0627\u0698 \u06a9\u0648\u0631 \u06cc\u0627 \u0628\u06cc\u0648\u067e\u0633\u06cc \u0633\u0631\u067e\u0627\u06cc\u06cc \u0645\u0645\u06a9\u0646 \u0627\u0633\u062a \u0636\u0627\u06cc\u0639\u0647\u0654 \u06a9\u0627\u0646\u0648\u0646\u06cc \u0631\u0627 \u0627\u0632 \u062f\u0633\u062a \u0628\u062f\u0647\u062f \u0648 \u0641\u0631\u0636 \u062e\u0648\u0646\u200c\u0631\u06cc\u0632\u06cc \u0628\u062f\u0648\u0646 \u0639\u0644\u062a \u0633\u0627\u062e\u062a\u0627\u0631\u06cc \u0631\u062d\u0645\u06cc (DUB) \u0628\u062f\u0648\u0646 \u0628\u0631\u0631\u0633\u06cc \u0622\u0646\u062f\u0648\u0645\u062a\u0631 \u0634\u062a\u0627\u0628\u0632\u062f\u0647 \u0627\u0633\u062a.",
   "reasons": ["\u06a9\u0648\u0631\u062a\u0627\u0698 \u06a9\u0648\u0631 \u0645\u0645\u06a9\u0646 \u0627\u0633\u062a \u0636\u0627\u06cc\u0639\u0647\u0654 \u06a9\u0627\u0646\u0648\u0646\u06cc \u0631\u0627 \u0627\u0632 \u062f\u0633\u062a \u0628\u062f\u0647\u062f.", "\u0628\u06cc\u0648\u067e\u0633\u06cc \u0633\u0631\u067e\u0627\u06cc\u06cc \u06a9\u0648\u0631 \u0646\u0633\u0628\u062a \u0628\u0647 \u0636\u0627\u06cc\u0639\u0647\u0654 \u06a9\u0627\u0646\u0648\u0646\u06cc \u06a9\u0645\u200c\u062f\u0642\u062a \u0627\u0633\u062a.", "\u0647\u06cc\u0633\u062a\u0631\u0648\u0633\u06a9\u0648\u067e\u06cc \u0628\u0627 \u062f\u06cc\u062f \u0645\u0633\u062a\u0642\u06cc\u0645 \u0628\u0647\u062a\u0631\u06cc\u0646 \u06af\u0627\u0645 \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u0641\u0631\u0636 DUB \u0628\u062f\u0648\u0646 \u0628\u0631\u0631\u0633\u06cc \u0647\u062f\u0641\u200c\u062f\u0627\u0631 \u0622\u0646\u062f\u0648\u0645\u062a\u0631 \u0634\u062a\u0627\u0628\u0632\u062f\u0647 \u0627\u0633\u062a."],
  },
  (28, 170): {
   "topic": "dermoidComplication",
   "lead": "\u0634\u0627\u06cc\u0639\u200c\u062a\u0631\u06cc\u0646 \u0639\u0627\u0631\u0636\u0647\u0654 \u06a9\u06cc\u0633\u062a \u062f\u0631\u0645\u0648\u0626\u06cc\u062f\u060c \u062a\u0648\u0631\u0633\u06cc\u0648\u0646 \u0627\u0633\u062a.",
   "interpretation": "\u06a9\u06cc\u0633\u062a\u200c\u0647\u0627\u06cc \u062f\u0631\u0645\u0648\u0626\u06cc\u062f (\u062a\u0631\u0627\u062a\u0648\u0645 \u06a9\u06cc\u0633\u062a\u06cc\u06a9 \u0628\u0627\u0644\u063a) \u0628\u0647\u200c\u062f\u0644\u06cc\u0644 \u0648\u0632\u0646 \u0648 \u0633\u0627\u0642\u0647\u060c \u0645\u0633\u062a\u0639\u062f \u067e\u06cc\u0686\u200c\u062e\u0648\u0631\u062f\u06af\u06cc (\u062a\u0648\u0631\u0633\u06cc\u0648\u0646) \u0647\u0633\u062a\u0646\u062f \u06a9\u0647 \u0634\u0627\u06cc\u0639\u200c\u062a\u0631\u06cc\u0646 \u0639\u0627\u0631\u0636\u0647 \u0627\u0633\u062a\u061b \u067e\u0627\u0631\u06af\u06cc \u0645\u06cc\u200c\u062a\u0648\u0627\u0646\u062f \u067e\u0631\u06cc\u062a\u0648\u0646\u06cc\u062a \u0634\u06cc\u0645\u06cc\u0627\u06cc\u06cc \u0627\u06cc\u062c\u0627\u062f \u06a9\u0646\u062f \u0648\u0644\u06cc \u06a9\u0645\u062a\u0631 \u0627\u0633\u062a\u061b \u062a\u0628\u062f\u06cc\u0644 \u0628\u062f\u062e\u06cc\u0645\u06cc \u0646\u0627\u062f\u0631 \u0648 \u062f\u0631 \u0633\u0646\u06cc\u0646 \u0628\u0627\u0644\u0627\u062a\u0631 \u062f\u06cc\u062f\u0647 \u0645\u06cc\u200c\u0634\u0648\u062f\u061b \u0646\u0627\u0632\u0627\u06cc\u06cc \u0639\u0627\u0631\u0636\u0647\u0654 \u0645\u0633\u062a\u0642\u06cc\u0645 \u062f\u0631\u0645\u0648\u0626\u06cc\u062f \u0646\u06cc\u0633\u062a.",
   "reasons": ["\u067e\u0627\u0631\u06af\u06cc \u06a9\u06cc\u0633\u062a \u06a9\u0645\u062a\u0631 \u0627\u0632 \u062a\u0648\u0631\u0633\u06cc\u0648\u0646 \u0634\u0627\u06cc\u0639 \u0627\u0633\u062a.", "\u062a\u0648\u0631\u0633\u06cc\u0648\u0646 \u0634\u0627\u06cc\u0639\u200c\u062a\u0631\u06cc\u0646 \u0639\u0627\u0631\u0636\u0647\u0654 \u06a9\u06cc\u0633\u062a \u062f\u0631\u0645\u0648\u0626\u06cc\u062f \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u062a\u0628\u062f\u06cc\u0644 \u0628\u0647 \u0628\u062f\u062e\u06cc\u0645\u06cc \u0646\u0627\u062f\u0631 \u0648 \u0628\u06cc\u0634\u062a\u0631 \u062f\u0631 \u0633\u0646\u06cc\u0646 \u0628\u0627\u0644\u0627 \u062f\u06cc\u062f\u0647 \u0645\u06cc\u200c\u0634\u0648\u062f.", "\u0646\u0627\u0632\u0627\u06cc\u06cc \u0639\u0627\u0631\u0636\u0647\u0654 \u0645\u0633\u062a\u0642\u06cc\u0645 \u06a9\u06cc\u0633\u062a \u062f\u0631\u0645\u0648\u0626\u06cc\u062f \u0645\u062d\u0633\u0648\u0628 \u0646\u0645\u06cc\u200c\u0634\u0648\u062f."],
  },
  (28, 171): {
   "topic": "molarFollowup",
   "lead": "\u067e\u0633 \u0627\u0632 \u0632\u0627\u06cc\u0645\u0627\u0646 \u0648\u0627\u0698\u06cc\u0646\u0627\u0644 \u062f\u0631 \u0633\u0627\u0628\u0642\u0647\u0654 \u0645\u0648\u0644\u060c \u062a\u0648\u0635\u06cc\u0647\u0654 \u06a9\u0644\u06cc\u062f\u06cc \u067e\u0627\u06cc\u0634 BHCG \u06f6 \u0647\u0641\u062a\u0647 \u0628\u0639\u062f \u0627\u0632 \u0632\u0627\u06cc\u0645\u0627\u0646 \u0627\u0633\u062a.",
   "interpretation": "\u062f\u0631 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0628\u0639\u062f\u06cc \u0628\u0639\u062f \u0627\u0632 \u062d\u0627\u0645\u0644\u06af\u06cc \u0645\u0648\u0627\u0644\u0631\u060c \u062e\u0637\u0631 \u0639\u0648\u062f \u067e\u0627\u06cc\u06cc\u0646 \u0627\u0645\u0627 \u0648\u062c\u0648\u062f \u062f\u0627\u0631\u062f \u0648 \u062a\u0634\u062e\u06cc\u0635 \u0632\u0648\u062f\u0647\u0646\u06af\u0627\u0645 \u0645\u0647\u0645 \u0627\u0633\u062a\u061b \u06a9\u0644\u06cc\u062f \u0627\u06cc\u0646 \u0622\u06cc\u062a\u0645 \u0628\u0647 \u067e\u0627\u06cc\u0634 BHCG \u06f6 \u0647\u0641\u062a\u0647\u200c\u0627\u06cc \u062a\u06a9\u06cc\u0647 \u062f\u0627\u0631\u062f\u061b \u0641\u0627\u0635\u0644\u0647\u0654 \u06a9\u0648\u062a\u0627\u0647\u200c\u062a\u0631 (\u0647\u0631 \u0647\u0641\u062a\u0647 \u062a\u0627 \u06f3 \u0647\u0641\u062a\u0647) \u062f\u0631\u0633\u062a \u0648\u0644\u06cc \u0645\u062c\u0627\u0632 \u0646\u06cc\u0633\u062a \u06a9\u0647 \u06af\u0632\u06cc\u0646\u0647\u0654 \u06f6 \u0647\u0641\u062a\u0647\u200c\u0627\u06cc \u067e\u0648\u0634\u0634 \u062f\u0647\u0646\u062f\u0647\u0654 \u06af\u0631\u0627\u0646 \u06cc\u0627\u062f\u06af\u0627\u0631\u06cc \u0627\u0633\u062a.",
   "reasons": ["BHCG \u062f\u0631 \u06f6 \u0647\u0641\u062a\u0647 \u0628\u0639\u062f \u0627\u0632 \u0632\u0627\u06cc\u0645\u0627\u0646 \u062a\u0648\u0635\u06cc\u0647\u0654 \u0645\u0631\u062c\u0639 \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u0647\u0631 \u0647\u0641\u062a\u0647 \u062a\u0627 \u06f3 \u0647\u0641\u062a\u0647 \u06af\u0632\u06cc\u0646\u0647\u0654 \u0628\u06cc\u0634\u200c\u062a\u0631 \u0645\u062d\u062a\u0627\u0637\u0627\u0646\u0647 \u0648 \u06af\u0631\u0627\u0646\u200c\u062a\u0631 \u0627\u0633\u062a.", "\u0633\u0648\u0646\u0648\u06af\u0631\u0627\u0641\u06cc \u06cc\u06a9\u200c\u0628\u0627\u0631 \u062f\u0631 \u06f6 \u0647\u0641\u062a\u0647 \u062c\u0627\u06cc \u067e\u0627\u06cc\u0634 BHCG \u0631\u0627 \u0646\u0645\u06cc\u200c\u06af\u06cc\u0631\u062f.", "\u0633\u0648\u0646\u0648\u06af\u0631\u0627\u0641\u06cc \u0645\u0627\u0647\u0627\u0646\u0647 \u062a\u0627 \u06f3 \u0645\u0627\u0647 \u062c\u0627\u06cc\u06af\u0632\u06cc\u0646 \u067e\u0627\u06cc\u0634 BHCG \u0646\u06cc\u0633\u062a."],
  },
  (28, 172): {
   "topic": "semenAbnormalNotNeed",
   "lead": "\u062f\u0631 \u0627\u0633\u067e\u0631\u0645\u0648\u06af\u0631\u0627\u0645 \u0645\u062e\u062a\u0644\u060c \u0628\u06cc\u0648\u067e\u0633\u06cc \u0628\u06cc\u0636\u0647 \u062f\u0631 \u0627\u0628\u062a\u062f\u0627\u06cc \u06a9\u0627\u0631\u0622\u067e \u0636\u0631\u0648\u0631\u06cc \u0646\u06cc\u0633\u062a\u061b \u0633\u0648\u0646\u0648\u06af\u0631\u0627\u0641\u06cc \u0648 \u0628\u0631\u0631\u0633\u06cc \u0647\u0648\u0631\u0645\u0648\u0646\u200c\u0647\u0627 \u0645\u0642\u062f\u0645\u200c\u062a\u0631\u0646\u062f.",
   "interpretation": "\u0627\u0631\u0632\u06cc\u0627\u0628\u06cc \u0627\u0648\u0644\u06cc\u0647\u0654 \u0627\u0633\u067e\u0631\u0645\u0648\u06af\u0631\u0627\u0645 \u0645\u062e\u062a\u0644 \u0634\u0627\u0645\u0644 \u062a\u06a9\u0631\u0627\u0631 \u062a\u0633\u062a\u060c \u0627\u0646\u062f\u0627\u0632\u0647\u200c\u06af\u06cc\u0631\u06cc \u0647\u0648\u0631\u0645\u0648\u0646\u200c\u0647\u0627 (FSH \u0648 LH \u0648 \u062a\u0633\u062a\u0648\u0633\u062a\u0631\u0648\u0646)\u060c \u0633\u0648\u0646\u0648\u06af\u0631\u0627\u0641\u06cc \u0628\u0631\u0627\u06cc \u0648\u0627\u0631\u06cc\u06a9\u0648\u0633\u0644 \u0648 \u062f\u0631 \u0645\u0648\u0627\u0631\u062f \u0622\u0632\u0648\u0627\u0633\u067e\u0631\u0645\u06cc\u060c \u06a9\u0627\u0631\u06cc\u0648\u062a\u06cc\u067e \u0648 \u0628\u0631\u0631\u0633\u06cc \u0645\u06cc\u06a9\u0631\u0648\u062f\u0644\u06cc\u0634\u0646 \u06a9\u0631\u0648\u0645\u0648\u0632\u0648\u0645 Y \u0627\u0633\u062a\u061b \u0628\u06cc\u0648\u067e\u0633\u06cc \u0628\u06cc\u0636\u0647 \u0641\u0642\u0637 \u062f\u0631 \u0622\u0632\u0648\u0627\u0633\u067e\u0631\u0645\u06cc \u067e\u0627\u06cc\u062f\u0627\u0631 \u0628\u0631\u0627\u06cc \u0627\u0641\u062a\u0631\u0627\u0642 \u0627\u0646\u0633\u062f\u0627\u062f \u0627\u0632 \u0646\u0627\u0631\u0633\u0627\u06cc\u06cc \u0633\u0627\u062e\u062a\u06cc \u0627\u0646\u062c\u0627\u0645 \u0645\u06cc\u200c\u0634\u0648\u062f \u0648 \u062f\u0631 \u0634\u0631\u0648\u0639 \u06a9\u0627\u0631\u0622\u067e \u0644\u0627\u0632\u0645 \u0646\u06cc\u0633\u062a.",
   "reasons": ["\u0627\u0646\u062f\u0627\u0632\u0647\u200c\u06af\u06cc\u0631\u06cc FSH \u0648 LH \u0648 \u062a\u0633\u062a\u0648\u0633\u062a\u0631\u0648\u0646 \u0628\u062e\u0634\u06cc \u0627\u0632 \u06a9\u0627\u0631\u0622\u067e \u0627\u0648\u0644\u06cc\u0647 \u0627\u0633\u062a.", "\u06a9\u0627\u0631\u06cc\u0648\u062a\u06cc\u067e \u062f\u0631 \u0622\u0632\u0648\u0627\u0633\u067e\u0631\u0645\u06cc \u06cc\u0627 \u0627\u0644\u06cc\u06af\u0648\u0627\u0633\u067e\u0631\u0645\u06cc \u0634\u062f\u06cc\u062f \u0644\u0627\u0632\u0645 \u0627\u0633\u062a.", "\u0628\u06cc\u0648\u067e\u0633\u06cc \u0628\u06cc\u0636\u0647 \u062f\u0631 \u0634\u0631\u0648\u0639 \u06a9\u0627\u0631\u0622\u067e \u0627\u0633\u067e\u0631\u0645\u0648\u06af\u0631\u0627\u0645 \u0645\u062e\u062a\u0644 \u0644\u0627\u0632\u0645 \u0646\u06cc\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u0633\u0648\u0646\u0648\u06af\u0631\u0627\u0641\u06cc \u0628\u0631\u0627\u06cc \u0628\u0631\u0631\u0633\u06cc \u0648\u0627\u0631\u06cc\u06a9\u0648\u0633\u0644 \u0627\u0646\u062c\u0627\u0645 \u0645\u06cc\u200c\u0634\u0648\u062f."],
  },
  (28, 173): {
   "topic": "bvClueCell",
   "lead": "Clue cell \u0628\u06cc\u0634 \u0627\u0632 \u06f2\u06f0\u066a \u0633\u0644\u0648\u0644\u200c\u0647\u0627\u06cc \u0627\u067e\u06cc\u200c\u062a\u0644\u06cc\u0627\u0644\u060c \u0645\u062e\u0635\u0648\u0635 \u0648\u0627\u0698\u06cc\u0646\u0648\u0632\u06cc\u0633 \u0628\u0627\u06a9\u062a\u0631\u06cc\u0627\u0644 \u0627\u0633\u062a.",
   "interpretation": "\u0648\u0627\u0698\u06cc\u0646\u0648\u0632\u06cc\u0633 \u0628\u0627\u06a9\u062a\u0631\u06cc\u0627\u0644 (BV) \u0628\u0627 \u0645\u0639\u06cc\u0627\u0631 \u0622\u0645\u0633\u0644 \u062a\u0639\u0631\u06cc\u0641 \u0645\u06cc\u200c\u0634\u0648\u062f: \u062a\u0631\u0634\u062d \u0647\u0645\u06af\u0646\u060c pH \u0628\u0627\u0644\u0627\u06cc \u06f4.\u06f5\u060c \u0628\u0648\u06cc \u0645\u0627\u0647\u06cc \u062f\u0631 \u062a\u0633\u062a \u0622\u0645\u06cc\u0646 \u0648 \u062d\u0636\u0648\u0631 \u0633\u0644\u0648\u0644\u200c\u0647\u0627\u06cc \u0633\u0631\u0646\u062e (Clue cell) \u0628\u06cc\u0634 \u0627\u0632 \u06f2\u06f0\u066a\u061b \u062a\u0631\u06cc\u06a9\u0648\u0645\u0648\u0646\u0627 \u0628\u0627 \u0645\u0634\u0627\u0647\u062f\u0647\u0654 \u062a\u0631\u06cc\u06a9\u0648\u0645\u0648\u0646\u0627\u0633 \u0645\u062a\u062d\u0631\u06a9\u060c \u0648\u0627\u0698\u06cc\u0646\u06cc\u062a \u0622\u062a\u0631\u0648\u0641\u06cc\u06a9 \u0628\u0627 \u06a9\u0627\u0647\u0634 \u0627\u0633\u062a\u0631\u0648\u0698\u0646 \u0648 \u0642\u0627\u0631\u0686\u06cc \u0628\u0627 \u0647\u06cc\u0641 \u062f\u0631 \u062a\u0633\u062a \u067e\u062a\u0627\u0633\u0647 \u062a\u0634\u062e\u06cc\u0635 \u062f\u0627\u062f\u0647 \u0645\u06cc\u200c\u0634\u0648\u062f.",
   "reasons": ["\u062a\u0631\u06cc\u06a9\u0648\u0645\u0648\u0646\u0627\u0633 \u0645\u062a\u062d\u0631\u06a9 \u062f\u0631 \u0633\u0648\u0622\u0628 \u0645\u0634\u0627\u0647\u062f\u0647 \u0645\u06cc\u200c\u0634\u0648\u062f \u0646\u0647 \u0633\u0644\u0648\u0644 \u0633\u0631\u0646\u062e.", "\u0648\u0627\u0698\u06cc\u0646\u06cc\u062a \u0622\u062a\u0631\u0648\u0641\u06cc\u06a9 \u0628\u0627 \u062e\u0634\u06a9\u06cc \u0648 \u06a9\u0645\u0628\u0648\u062f \u0627\u0633\u062a\u0631\u0648\u0698\u0646 \u0647\u0645\u0631\u0627\u0647 \u0627\u0633\u062a.", "\u0648\u0627\u0698\u06cc\u0646\u06cc\u062a \u0642\u0627\u0631\u0686\u06cc \u0647\u0627\u06cc\u0641\u200c\u0647\u0627 \u062f\u0631 \u062a\u0633\u062a \u067e\u062a\u0627\u0633\u0647 (KOH) \u062f\u0627\u0631\u062f.", "\u0633\u0644\u0648\u0644 \u0633\u0631\u0646\u062e \u0628\u06cc\u0634 \u0627\u0632 \u06f2\u06f0\u066a\u060c \u0645\u0639\u06cc\u0627\u0631 \u0627\u062e\u062a\u0635\u0627\u0635\u06cc BV \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d."],
  },
  (28, 174): {
   "topic": "epRiskFactorsExcept",
   "lead": "\u0633\u0627\u0628\u0642\u0647\u0654 \u0633\u0632\u0627\u0631\u06cc\u0646 \u0642\u0628\u0644\u06cc \u062c\u0632\u0648 \u0641\u0627\u06a9\u062a\u0648\u0631\u0647\u0627\u06cc \u062e\u0637\u0631 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u062e\u0627\u0631\u062c\u200c\u0631\u062d\u0645\u06cc \u0646\u06cc\u0633\u062a.",
   "interpretation": "\u0641\u0627\u06a9\u062a\u0648\u0631\u0647\u0627\u06cc \u062e\u0637\u0631 EP \u0634\u0627\u0645\u0644 \u0639\u0641\u0648\u0646\u062a \u0644\u06af\u0646 \u0642\u0628\u0644\u06cc (PID)\u060c \u062c\u0631\u0627\u062d\u06cc \u06cc\u0627 \u0622\u0633\u06cc\u0628 \u0644\u0648\u0644\u0647\u060c \u0633\u0627\u0628\u0642\u0647\u0654 \u0628\u0633\u062a\u0646 \u0644\u0648\u0644\u0647\u060c EP \u0642\u0628\u0644\u06cc\u060c \u062a\u06a9\u0646\u06cc\u06a9\u200c\u0647\u0627\u06cc \u06a9\u0645\u06a9\u200c\u0628\u0627\u0631\u0648\u0631\u06cc\u060c \u0633\u06cc\u06af\u0627\u0631 \u0648 \u0634\u0631\u06a9\u0627\u06cc \u0645\u062a\u0639\u062f\u062f \u062c\u0646\u0633\u06cc \u0627\u0633\u062a\u061b \u0633\u0632\u0627\u0631\u06cc\u0646 \u0642\u0628\u0644\u06cc \u0628\u0647\u200c\u0637\u0648\u0631 \u0645\u0633\u062a\u0642\u06cc\u0645 \u062f\u0631 \u0627\u06cc\u0646 \u0641\u0647\u0631\u0633\u062a \u0642\u0631\u0627\u0631 \u0646\u0645\u06cc\u200c\u06af\u06cc\u0631\u062f.",
   "reasons": ["\u0634\u0631\u06a9\u0627\u06cc \u062c\u0646\u0633\u06cc \u0645\u062a\u0639\u062f\u062f \u0627\u0632 \u0637\u0631\u06cc\u0642 \u0627\u0641\u0632\u0627\u06cc\u0634 PID\u060c \u062e\u0637\u0631 EP \u0631\u0627 \u0628\u0627\u0644\u0627 \u0645\u06cc\u200c\u0628\u0631\u0646\u062f.", "\u0628\u0633\u062a\u0646 \u0644\u0648\u0644\u0647 \u062f\u0631 \u0635\u0648\u0631\u062a \u0634\u06a9\u0633\u062a\u060c \u0627\u062d\u062a\u0645\u0627\u0644 EP \u0631\u0627 \u0627\u0641\u0632\u0627\u06cc\u0634 \u0645\u06cc\u200c\u062f\u0647\u062f.", "\u0633\u0627\u0628\u0642\u0647\u0654 \u0633\u0632\u0627\u0631\u06cc\u0646 \u062c\u0632\u0648 \u0641\u0627\u06a9\u062a\u0648\u0631\u0647\u0627\u06cc \u0627\u0635\u0644\u06cc EP \u0634\u0646\u0627\u062e\u062a\u0647 \u0646\u0645\u06cc\u200c\u0634\u0648\u062f\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u0639\u0641\u0648\u0646\u062a \u0644\u06af\u0646 \u0642\u0628\u0644\u06cc \u06cc\u06a9\u06cc \u0627\u0632 \u0642\u0648\u06cc\u200c\u062a\u0631\u06cc\u0646 \u0641\u0627\u06a9\u062a\u0648\u0631\u0647\u0627\u06cc \u062e\u0637\u0631 EP \u0627\u0633\u062a."],
  },
  (28, 175): {
   "topic": "vbacPrerequisite",
   "lead": "\u062f\u0631 \u0633\u0632\u0627\u0631\u06cc\u0646 \u0642\u0628\u0644\u06cc \u0648 \u062f\u0631 \u0646\u0638\u0631 \u06af\u0631\u0641\u062a\u0646 VBAC\u060c \u062f\u0633\u062a\u0631\u0633\u06cc \u0628\u0647 \u0634\u0631\u062d \u0639\u0645\u0644 \u0642\u0628\u0644\u06cc \u0636\u0631\u0648\u0631\u06cc \u0627\u0633\u062a.",
   "interpretation": "\u062f\u0631 \u0627\u0631\u0632\u06cc\u0627\u0628\u06cc \u06a9\u0627\u0646\u062f\u06cc\u062f\u0627\u06cc \u0632\u0627\u06cc\u0645\u0627\u0646 \u0637\u0628\u06cc\u0639\u06cc \u067e\u0633 \u0627\u0632 \u0633\u0632\u0627\u0631\u06cc\u0646 (VBAC)\u060c \u062a\u0639\u06cc\u06cc\u0646 \u0646\u0648\u0639 \u0633\u06a9\u0627\u0631 \u0642\u0628\u0644\u06cc \u0631\u062d\u0645 (\u0628\u0631\u0634 \u062a\u062d\u062a\u0627\u0646\u06cc \u0639\u0631\u0636\u06cc \u062f\u0631 \u0628\u0631\u0627\u0628\u0631 \u0628\u0631\u0634 \u0639\u0645\u0648\u062f\u06cc) \u0628\u0631\u0627\u06cc \u067e\u06cc\u0634\u200c\u0628\u06cc\u0646\u06cc \u062e\u0637\u0631 \u067e\u0627\u0631\u0647\u200c\u0634\u062f\u0646 \u0631\u062d\u0645 \u0636\u0631\u0648\u0631\u06cc \u0627\u0633\u062a\u061b \u0628\u0646\u0627\u0628\u0631\u0627\u06cc\u0646 \u062f\u0633\u062a\u0631\u0633\u06cc \u0628\u0647 \u0634\u0631\u062d \u0639\u0645\u0644 \u0642\u0628\u0644\u06cc \u0627\u0635\u0644\u06cc\u200c\u062a\u0631\u06cc\u0646 \u067e\u06cc\u0634\u200c\u0646\u06cc\u0627\u0632 \u0627\u0633\u062a. \u0648\u0632\u0646 \u0645\u0627\u062f\u0631 \u0648 \u0633\u0646 \u06a9\u0645\u062a\u0631 \u0627\u0632 \u06f4\u06f0 \u062f\u0631 \u0645\u0634\u0627\u0648\u0631\u0647 \u06a9\u0645\u06a9\u200c\u06a9\u0646\u0646\u062f\u0647\u200c\u0627\u0646\u062f \u0627\u0645\u0627 \u0634\u0631\u0637 \u0642\u0637\u0639\u06cc \u0646\u06cc\u0633\u062a\u0646\u062f \u0648 \u0634\u06a9\u0644 \u0628\u0631\u0634 \u0631\u0648\u06cc \u067e\u0648\u0633\u062a \u0628\u06cc\u0627\u0646\u06af\u0631 \u0646\u0648\u0639 \u0633\u06a9\u0627\u0631 \u0631\u062d\u0645 \u0646\u06cc\u0633\u062a.",
   "reasons": ["\u0648\u0632\u0646 \u0645\u0627\u062f\u0631 \u062f\u0631 \u0645\u0634\u0627\u0648\u0631\u0647 \u0644\u062d\u0627\u0638 \u0645\u06cc\u200c\u0634\u0648\u062f \u0648\u0644\u06cc \u0634\u0631\u0637 \u0636\u0631\u0648\u0631\u06cc \u0646\u06cc\u0633\u062a.", "\u0634\u06a9\u0644 \u0628\u0631\u0634 \u0631\u0648\u06cc \u067e\u0648\u0633\u062a \u0628\u06cc\u0627\u0646\u06af\u0631 \u0646\u0648\u0639 \u0633\u06a9\u0627\u0631 \u0631\u062d\u0645 \u0646\u06cc\u0633\u062a.", "\u0633\u0646 \u06a9\u0645\u062a\u0631 \u0627\u0632 \u06f4\u06f0 \u0634\u0631\u0637 \u06a9\u0644\u06cc \u0628\u0631\u0627\u06cc \u0632\u0627\u06cc\u0645\u0627\u0646 \u0637\u0628\u06cc\u0639\u06cc \u067e\u0633 \u0627\u0632 \u0633\u0632\u0627\u0631\u06cc\u0646 \u0646\u06cc\u0633\u062a.", "\u0634\u0631\u062d \u0639\u0645\u0644 \u0642\u0628\u0644\u06cc \u0645\u0647\u0645\u200c\u062a\u0631\u06cc\u0646 \u067e\u06cc\u0634\u200c\u0646\u06cc\u0627\u0632 \u0627\u0631\u0632\u06cc\u0627\u0628\u06cc \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d."],
  },
  (28, 176): {
   "topic": "threatenedAbortion",
   "lead": "\u062e\u0648\u0646\u200c\u0631\u06cc\u0632\u06cc + \u0633\u0631\u0648\u06cc\u06a9\u0633 \u0628\u0633\u062a\u0647 + \u0636\u0631\u0628\u0627\u0646 \u0642\u0644\u0628 \u0645\u0634\u0627\u0647\u062f\u0647\u200c\u0634\u062f\u0647\u060c \u062a\u0639\u0631\u06cc\u0641 \u0633\u0642\u0637 \u062a\u0647\u062f\u06cc\u062f\u06a9\u0646\u0646\u062f\u0647 (\u062a\u0647\u062f\u06cc\u062f \u0628\u0647 \u0633\u0642\u0637) \u0627\u0633\u062a.",
   "interpretation": "\u062f\u0631 \u062a\u0647\u062f\u06cc\u062f \u0628\u0647 \u0633\u0642\u0637\u060c \u062e\u0648\u0646\u200c\u0631\u06cc\u0632\u06cc \u067e\u06cc\u0634 \u0627\u0632 \u0647\u0641\u062a\u0647\u0654 \u06f2\u06f0 \u0631\u062e \u062f\u0627\u062f\u0647 \u0648\u0644\u06cc \u0633\u0631\u0648\u06cc\u06a9\u0633 \u0628\u0633\u062a\u0647 \u0627\u0633\u062a \u0648 \u0645\u062d\u0635\u0648\u0644\u0627\u062a \u062e\u0627\u0631\u062c \u0646\u0634\u062f\u0647\u200c\u0627\u0646\u062f\u061b \u062f\u0631 \u0627\u062c\u062a\u0646\u0627\u0628\u200c\u0646\u0627\u067e\u0630\u06cc\u0631 \u0633\u0631\u0648\u06cc\u06a9\u0633 \u0628\u0627\u0632 \u0627\u0633\u062a\u061b \u062f\u0631 \u0633\u0642\u0637 \u0641\u0631\u0627\u0645\u0648\u0634\u200c\u0634\u062f\u0647 \u062c\u0646\u06cc\u0646 \u0641\u0648\u062a \u0634\u062f\u0647 \u0627\u0645\u0627 \u0633\u0631\u0648\u06cc\u06a9\u0633 \u0628\u0633\u062a\u0647 \u0648 \u0639\u0644\u0627\u0626\u0645 \u06a9\u0645 \u0627\u0633\u062a\u061b \u062f\u0631 \u0633\u0642\u0637 \u0646\u0627\u0642\u0635 \u0642\u0633\u0645\u062a\u06cc \u0627\u0632 \u0628\u0627\u0641\u062a \u062e\u0627\u0631\u062c \u0634\u062f\u0647 \u0627\u0633\u062a.",
   "reasons": ["\u0627\u062c\u062a\u0646\u0627\u0628\u200c\u0646\u0627\u067e\u0630\u06cc\u0631 \u0628\u0627 \u0628\u0627\u0632 \u0628\u0648\u062f\u0646 \u0633\u0631\u0648\u06cc\u06a9\u0633 \u062a\u0639\u0631\u06cc\u0641 \u0645\u06cc\u200c\u0634\u0648\u062f.", "\u0633\u0631\u0648\u06cc\u06a9\u0633 \u0628\u0633\u062a\u0647 + \u0636\u0631\u0628\u0627\u0646 \u0642\u0644\u0628 \u0645\u0634\u0627\u0647\u062f\u0647\u200c\u0634\u062f\u0647 = \u062a\u0647\u062f\u06cc\u062f \u0628\u0647 \u0633\u0642\u0637\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u0633\u0642\u0637 \u0641\u0631\u0627\u0645\u0648\u0634\u200c\u0634\u062f\u0647 \u0628\u0627 \u0645\u0631\u06af \u062c\u0646\u06cc\u0646 \u0648 \u0633\u0631\u0648\u06cc\u06a9\u0633 \u0628\u0633\u062a\u0647 \u062a\u0639\u0631\u06cc\u0641 \u0645\u06cc\u200c\u0634\u0648\u062f.", "\u0633\u0642\u0637 \u0646\u0627\u0642\u0635 \u0628\u0627 \u062e\u0631\u0648\u062c \u0628\u062e\u0634\u06cc \u0627\u0632 \u0628\u0627\u0641\u062a \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0647\u0645\u0631\u0627\u0647 \u0627\u0633\u062a."],
  },
  (28, 177): {
   "topic": "quadrivalentHpv",
   "lead": "\u0648\u0627\u06a9\u0633\u0646 \u0686\u0647\u0627\u0631\u06af\u0627\u0646\u0647\u0654 HPV \u062f\u0631 \u0628\u0647\u062a\u0631\u06cc\u0646 \u062d\u0627\u0644\u062a \u0628\u06cc\u0646 \u06f9 \u062a\u0627 \u06f2\u06f6 \u0633\u0627\u0644 \u062a\u0632\u0631\u06cc\u0642 \u0645\u06cc\u200c\u0634\u0648\u062f.",
   "interpretation": "\u0648\u0627\u06a9\u0633\u0646 \u0686\u0647\u0627\u0631\u06af\u0627\u0646\u0647\u0654 HPV \u062f\u0631 \u062f\u062e\u062a\u0631\u0627\u0646 \u0648 \u0632\u0646\u0627\u0646 \u06f9 \u062a\u0627 \u06f2\u06f6 \u0633\u0627\u0644 \u062a\u0648\u0635\u06cc\u0647 \u0645\u06cc\u200c\u0634\u0648\u062f\u061b \u067e\u0627\u067e \u0627\u0633\u0645\u06cc\u0631 \u0647\u0645\u0686\u0646\u0627\u0646 \u0644\u0627\u0632\u0645 \u0627\u0633\u062a \u0632\u06cc\u0631\u0627 \u0648\u0627\u06a9\u0633\u0646 \u0647\u0645\u0647\u0654 \u062a\u06cc\u067e\u200c\u0647\u0627\u06cc \u062e\u0637\u0631\u0646\u0627\u06a9 \u0631\u0627 \u067e\u0648\u0634\u0634 \u0646\u0645\u06cc\u200c\u062f\u0647\u062f\u061b \u0628\u0631\u0646\u0627\u0645\u0647\u0654 \u0635\u062d\u06cc\u062d \u0645\u0627\u0647\u200c\u0647\u0627\u06cc \u06f0 \u0648 \u06f2 \u0648 \u06f6 \u0627\u0633\u062a \u0648 \u0645\u062f\u062a \u062f\u0642\u06cc\u0642 \u0627\u06cc\u0645\u0646\u06cc\u200c\u0632\u0627\u06cc\u06cc \u0628\u0631\u0627\u06cc \u062a\u0639\u06cc\u06cc\u0646 \u062f\u0642\u06cc\u0642\u200c\u062a\u0631 \u062f\u0631 \u062d\u0627\u0644 \u0628\u0631\u0631\u0633\u06cc \u0627\u0633\u062a (\u0639\u062f\u0645 \u0648\u062c\u0648\u062f \u0634\u0648\u0627\u0647\u062f \u0642\u0637\u0639\u06cc \u0628\u0631\u0627\u06cc \u06f1\u06f0 \u0633\u0627\u0644). \u06af\u0632\u06cc\u0646\u0647\u0654 \u0635\u062d\u06cc\u062d: \u062f\u0627\u0645\u0646\u0647\u0654 \u0633\u0646\u06cc \u06f9 \u062a\u0627 \u06f2\u06f6.",
   "reasons": ["\u067e\u0627\u067e \u0627\u0633\u0645\u06cc\u0631 \u067e\u0633 \u0627\u0632 \u0648\u0627\u06a9\u0633\u06cc\u0646\u0627\u0633\u06cc\u0648\u0646 \u0647\u0645\u0686\u0646\u0627\u0646 \u0644\u0627\u0632\u0645 \u0627\u0633\u062a.", "\u062f\u0642\u062a \u0645\u062f\u062a \u0627\u06cc\u0645\u0646\u06cc\u200c\u0632\u0627\u06cc\u06cc \u0628\u0631\u0627\u06cc \u06f1\u06f0 \u0633\u0627\u0644 \u062f\u0642\u06cc\u0642\u0627\u064b \u0627\u062b\u0628\u0627\u062a \u0646\u0634\u062f\u0647 \u0627\u0633\u062a.", "\u0628\u0631\u0646\u0627\u0645\u0647\u0654 \u0635\u062d\u06cc\u062d \u0645\u0627\u0647\u200c\u0647\u0627\u06cc \u06f0 \u0648 \u06f2 \u0648 \u06f6 \u0627\u0633\u062a \u0646\u0647 \u06f0 \u0648 \u06f3 \u0648 \u06f1\u06f2.", "\u06af\u0631\u0648\u0647 \u0647\u062f\u0641 \u0648\u0627\u06a9\u0633\u0646\u060c \u062f\u062e\u062a\u0631\u0627\u0646 \u0648 \u0632\u0646\u0627\u0646 \u06f9 \u062a\u0627 \u06f2\u06f6 \u0633\u0627\u0644 \u0647\u0633\u062a\u0646\u062f\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d."],
  },
  (28, 178): {
   "topic": "vaccineContraindicatedPreg",
   "lead": "\u0648\u0627\u06a9\u0633\u0646\u200c\u0647\u0627\u06cc \u0632\u0646\u062f\u0647\u0654 \u062a\u0636\u0639\u06cc\u0641\u200c\u0634\u062f\u0647 \u062f\u0631 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0645\u0645\u0646\u0648\u0639\u200c\u0627\u0646\u062f\u061b \u0627\u0648\u0631\u06cc\u0648\u0646 (\u062c\u0632\u0621 MMR) \u0627\u0632 \u0627\u06cc\u0646 \u062f\u0633\u062a\u0647 \u0627\u0633\u062a.",
   "interpretation": "\u0648\u0627\u06a9\u0633\u0646\u200c\u0647\u0627\u06cc \u0632\u0646\u062f\u0647\u0654 \u062a\u0636\u0639\u06cc\u0641\u200c\u0634\u062f\u0647 \u062f\u0631 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0645\u0645\u0646\u0648\u0639\u200c\u0627\u0646\u062f\u061b \u0627\u0648\u0631\u06cc\u0648\u0646 \u0628\u0647\u200c\u0639\u0646\u0648\u0627\u0646 \u062c\u0632\u0621 \u0648\u0627\u06a9\u0633\u0646 \u0633\u0631\u062e\u062c\u0647-\u0633\u0631\u062e\u06a9-\u0627\u0648\u0631\u06cc\u0648\u0646 (MMR) \u062f\u0631 \u0627\u06cc\u0646 \u06af\u0631\u0648\u0647 \u0627\u0633\u062a\u061b \u0628\u0631\u0639\u06a9\u0633\u060c \u0647\u067e\u0627\u062a\u06cc\u062a B \u0648 \u0622\u0646\u0641\u0648\u0644\u0627\u0646\u0632\u0627 \u0648 \u0622\u0633\u0644\u0648\u0644\u0627\u0631 \u0633\u06cc\u0627\u0647\u200c\u0633\u0631\u0641\u0647 \u062f\u0631 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u062a\u0648\u0635\u06cc\u0647 \u0645\u06cc\u200c\u0634\u0648\u0646\u062f \u0648 \u0647\u067e\u0627\u062a\u06cc\u062a A \u062f\u0631 \u0645\u0648\u0627\u0631\u062f \u062e\u0627\u0635 \u0642\u0627\u0628\u0644 \u0627\u0633\u062a\u0641\u0627\u062f\u0647 \u0627\u0633\u062a. \u0628\u0646\u0627\u0628\u0631\u0627\u06cc\u0646 \u0627\u0648\u0631\u06cc\u0648\u0646 \u06af\u0632\u06cc\u0646\u0647\u0654 \u062f\u0631\u0633\u062a \u0627\u0633\u062a.",
   "reasons": ["\u0627\u0648\u0631\u06cc\u0648\u0646 \u0628\u062e\u0634\u06cc \u0627\u0632 \u0648\u0627\u06a9\u0633\u0646 \u0632\u0646\u062f\u0647\u0654 MMR \u0627\u0633\u062a \u0648 \u062f\u0631 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0645\u0645\u0646\u0648\u0639 \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u0647\u067e\u0627\u062a\u06cc\u062a B \u062f\u0631 \u0635\u0648\u0631\u062a \u0627\u0646\u062f\u06cc\u06a9\u0627\u0633\u06cc\u0648\u0646 \u062f\u0631 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0645\u062c\u0627\u0632 \u0627\u0633\u062a.", "\u0622\u0646\u0641\u0648\u0644\u0627\u0646\u0632\u0627 \u062f\u0631 \u0647\u0631 \u0633\u0647\u200c\u0645\u0627\u0647\u0647\u0654 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u062a\u0648\u0635\u06cc\u0647 \u0645\u06cc\u200c\u0634\u0648\u062f.", "\u0647\u067e\u0627\u062a\u06cc\u062a A \u062f\u0631 \u0634\u0631\u0627\u06cc\u0637 \u062e\u0627\u0635 \u0645\u062b\u0644 \u0633\u0641\u0631 \u0628\u0647\u200c\u06a9\u0627\u0631 \u0645\u06cc\u200c\u0631\u0648\u062f."],
  },
  (28, 179): {
   "topic": "infertilitySemenFirst",
   "lead": "\u0627\u0648\u0644\u06cc\u0646 \u0622\u0632\u0645\u0627\u06cc\u0634 \u062f\u0631 \u06a9\u0627\u0631\u0622\u067e \u0646\u0627\u0628\u0627\u0631\u0648\u0631\u06cc\u060c \u0633\u0645\u0646 \u0622\u0646\u0627\u0644\u06cc\u0632 (\u0622\u0646\u0627\u0644\u06cc\u0632 \u0645\u0627\u06cc\u0639 \u0645\u0646\u06cc) \u0627\u0633\u062a.",
   "interpretation": "\u0628\u0631\u0631\u0633\u06cc \u0645\u0627\u06cc\u0639 \u0645\u0646\u06cc \u0628\u0647\u200c\u062f\u0644\u06cc\u0644 \u0633\u0647\u0648\u0644\u062a\u060c \u0627\u0631\u0632\u0627\u0646\u06cc \u0648 \u0627\u0647\u0645\u06cc\u062a \u0645\u0624\u0644\u0641\u0647\u200c\u0647\u0627\u06cc \u0645\u0631\u062f\u0627\u0646\u0647 \u062e\u0637 \u0627\u0648\u0644 \u0627\u0633\u062a\u061b \u0633\u067e\u0633 \u0627\u0631\u0632\u06cc\u0627\u0628\u06cc \u062a\u062e\u0645\u06a9\u200c\u06af\u0630\u0627\u0631\u06cc \u0648 \u0633\u0648\u0646\u0648\u06af\u0631\u0627\u0641\u06cc \u0648 \u0647\u06cc\u0633\u062a\u0631\u0648\u0633\u0627\u0644\u067e\u0646\u06af\u0648\u06af\u0631\u0627\u0641\u06cc \u0648 \u062f\u0631 \u0646\u0647\u0627\u06cc\u062a \u0644\u0627\u067e\u0627\u0631\u0648\u0633\u06a9\u0648\u067e\u06cc\u061b TSH/\u067e\u0631\u0648\u0644\u0627\u06a9\u062a\u06cc\u0646 \u062f\u0631 \u0635\u0648\u0631\u062a \u0633\u0627\u0628\u0642\u0647\u0654 \u06af\u0627\u0644\u0627\u06a9\u062a\u0648\u0631\u0647 \u06cc\u0627 \u0642\u0627\u0639\u062f\u06af\u06cc \u0646\u0627\u0645\u0646\u0638\u0645 \u0628\u0631\u0631\u0633\u06cc \u0645\u06cc\u200c\u0634\u0648\u062f.",
   "reasons": ["TSH/\u067e\u0631\u0648\u0644\u0627\u06a9\u062a\u06cc\u0646 \u062f\u0631 \u0635\u0648\u0631\u062a \u0646\u0642\u0635 \u062a\u062e\u0645\u06a9\u200c\u06af\u0630\u0627\u0631\u06cc/\u06af\u0627\u0644\u0627\u06a9\u062a\u0648\u0631\u0647 \u062f\u0631\u062e\u0648\u0627\u0633\u062a \u0645\u06cc\u200c\u0634\u0648\u062f.", "\u0633\u0645\u0646 \u0622\u0646\u0627\u0644\u06cc\u0632 \u0633\u0627\u062f\u0647\u200c\u062a\u0631\u06cc\u0646 \u0648 \u0627\u0648\u0644\u06cc\u0646 \u0628\u0631\u0631\u0633\u06cc \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u0644\u0627\u067e\u0627\u0631\u0648\u0633\u06a9\u0648\u067e\u06cc \u062f\u0631 \u0645\u0631\u062d\u0644\u0647\u0654 \u067e\u0627\u06cc\u0627\u0646\u06cc \u06a9\u0627\u0631\u0622\u067e \u0642\u0631\u0627\u0631 \u062f\u0627\u0631\u062f.", "\u0633\u0648\u0646\u0648\u06af\u0631\u0627\u0641\u06cc \u062a\u062e\u0645\u062f\u0627\u0646 \u0628\u0631\u0627\u06cc \u0627\u0631\u0632\u06cc\u0627\u0628\u06cc \u062a\u062e\u0645\u06a9\u200c\u06af\u0630\u0627\u0631\u06cc \u0628\u0639\u062f \u0627\u0632 \u0627\u0633\u067e\u0631\u0645\u0648\u06af\u0631\u0627\u0645 \u0627\u0633\u062a."],
  },
  (28, 180): {
   "topic": "simpleCystObserve",
   "lead": "\u06a9\u06cc\u0633\u062a \u0633\u0627\u062f\u0647\u0654 \u06f5 \u0633\u0627\u0646\u062a\u06cc \u0628\u0627 \u062c\u062f\u0627\u0631 \u0646\u0627\u0632\u06a9 \u0648 \u0628\u062f\u0648\u0646 \u0627\u06a9\u0648\u06cc \u062f\u0627\u062e\u0644\u06cc\u060c \u0627\u063a\u0644\u0628 \u0641\u06cc\u0632\u06cc\u0648\u0644\u0648\u0698\u06cc\u06a9 \u0627\u0633\u062a \u0648 \u067e\u06cc\u06af\u06cc\u0631\u06cc \u0628\u0627 \u062a\u06a9\u0631\u0627\u0631 \u0633\u0648\u0646\u0648\u06af\u0631\u0627\u0641\u06cc \u06a9\u0627\u0641\u06cc \u0627\u0633\u062a.",
   "interpretation": "\u06a9\u06cc\u0633\u062a\u200c\u0647\u0627\u06cc \u0633\u0627\u062f\u0647\u0654 \u0628\u0627 \u0642\u0637\u0631 \u062d\u062f\u0648\u062f \u06f5 \u0633\u0627\u0646\u062a\u06cc\u200c\u0645\u062a\u0631 \u062f\u0631 \u0632\u0646\u0627\u0646 \u062c\u0648\u0627\u0646 \u0645\u0639\u0645\u0648\u0644\u0627\u064b \u0641\u06cc\u0632\u06cc\u0648\u0644\u0648\u0698\u06cc\u06a9 (\u06a9\u06cc\u0633\u062a \u0641\u0648\u0644\u06cc\u06a9\u0648\u0644\u06cc \u06cc\u0627 \u062c\u0633\u0645 \u0632\u0631\u062f) \u0647\u0633\u062a\u0646\u062f\u061b \u062a\u0648\u0635\u06cc\u0647\u0654 \u0627\u0633\u062a\u0627\u0646\u062f\u0627\u0631\u062f \u062a\u06a9\u0631\u0627\u0631 \u0633\u0648\u0646\u0648\u06af\u0631\u0627\u0641\u06cc \u062f\u0631 \u06f6 \u062a\u0627 \u06f1\u06f2 \u0647\u0641\u062a\u0647 \u0628\u0639\u062f \u06cc\u0627 \u067e\u0633 \u0627\u0632 \u0642\u0627\u0639\u062f\u06af\u06cc \u0628\u0639\u062f\u06cc \u0627\u0633\u062a\u061b \u0644\u0627\u067e\u0627\u0631\u0627\u062a\u0648\u0645\u06cc \u06cc\u0627 \u0644\u0627\u067e\u0627\u0631\u0648\u0633\u06a9\u0648\u067e\u06cc \u0628\u0631\u0627\u06cc \u06a9\u06cc\u0633\u062a\u200c\u0647\u0627\u06cc \u0628\u0632\u0631\u06af\u060c \u067e\u06cc\u0686\u06cc\u062f\u0647 \u06cc\u0627 \u0639\u0644\u0627\u0645\u062a\u200c\u062f\u0627\u0631 \u062f\u0631 \u0646\u0638\u0631 \u06af\u0631\u0641\u062a\u0647 \u0645\u06cc\u200c\u0634\u0648\u062f \u0648 \u0628\u0633\u062a\u0631\u06cc \u0628\u062f\u0648\u0646 \u0639\u0644\u0627\u0645\u062a \u0644\u0627\u0632\u0645 \u0646\u06cc\u0633\u062a.",
   "reasons": ["\u0644\u0627\u067e\u0627\u0631\u0627\u062a\u0648\u0645\u06cc \u062f\u0631 \u06a9\u06cc\u0633\u062a \u0633\u0627\u062f\u0647\u0654 5cm \u062c\u0648\u0627\u0646 \u063a\u06cc\u0631\u0636\u0631\u0648\u0631\u06cc \u0627\u0633\u062a.", "\u0628\u0633\u062a\u0631\u06cc \u0635\u0631\u0641\u0627\u064b \u0646\u0638\u0627\u0631\u062a\u06cc \u0628\u062f\u0648\u0646 \u0639\u0644\u0627\u0645\u062a \u0627\u0646\u062c\u0627\u0645 \u0646\u0645\u06cc\u200c\u0634\u0648\u062f.", "\u062a\u06a9\u0631\u0627\u0631 \u0633\u0648\u0646\u0648\u06af\u0631\u0627\u0641\u06cc \u0628\u0631\u0627\u06cc \u0627\u0631\u0632\u06cc\u0627\u0628\u06cc \u0641\u06cc\u0632\u06cc\u0648\u0644\u0648\u0698\u06cc\u06a9 \u0628\u0648\u062f\u0646\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u0644\u0627\u067e\u0627\u0631\u0648\u0633\u06a9\u0648\u067e\u06cc \u062f\u0631 \u06a9\u06cc\u0633\u062a \u0633\u0627\u062f\u0647\u0654 \u06a9\u0648\u0686\u06a9 \u062e\u0637 \u0627\u0648\u0644 \u0646\u06cc\u0633\u062a."],
  },
  (28, 181): {
   "topic": "breastfeedingAllowed",
   "lead": "\u0645\u0627\u062f\u0631 \u0628\u0627 HBsAg \u0645\u062b\u0628\u062a \u0645\u06cc\u200c\u062a\u0648\u0627\u0646\u062f \u0634\u06cc\u0631\u062f\u0647\u06cc \u062f\u0627\u0634\u062a\u0647 \u0628\u0627\u0634\u062f.",
   "interpretation": "\u062f\u0631 \u0645\u0627\u062f\u0631 \u0628\u0627 \u0622\u0646\u062a\u06cc\u200c\u0698\u0646 \u0633\u0637\u062d\u06cc \u0647\u067e\u0627\u062a\u06cc\u062a B \u0645\u062b\u0628\u062a\u060c \u0634\u06cc\u0631\u062f\u0647\u06cc (\u0628\u0647\u200c\u0648\u06cc\u0698\u0647 \u0628\u0627 \u0627\u06cc\u0645\u0646\u200c\u0633\u0627\u0632\u06cc \u0633\u0631\u0645\u06cc \u0648\u0627\u06a9\u0633\u0646 \u0646\u0648\u0632\u0627\u062f) \u0645\u0646\u0639 \u0646\u062f\u0627\u0631\u062f\u061b \u0645\u0646\u0639\u200c\u0647\u0627\u06cc \u0634\u06cc\u0631\u062f\u0647\u06cc \u0634\u0627\u0645\u0644 \u06af\u0627\u0644\u0627\u06a9\u062a\u0648\u0632\u0645\u06cc \u0646\u0648\u0632\u0627\u062f\u060c \u062a\u0648\u0628\u0631\u06a9\u0644\u0648\u0632 \u0641\u0639\u0627\u0644 \u062f\u0631\u0645\u0627\u0646\u200c\u0646\u0634\u062f\u0647 \u0648 \u062f\u0631\u0645\u0627\u0646 \u0645\u0627\u062f\u0631 \u0628\u0627 \u0627\u06cc\u0632\u0648\u062a\u0648\u067e \u0631\u0627\u062f\u06cc\u0648\u0627\u06a9\u062a\u06cc\u0648 \u0627\u0633\u062a.",
   "reasons": ["\u062f\u0631\u0645\u0627\u0646 \u0628\u0627 \u0627\u06cc\u0632\u0648\u062a\u0648\u067e \u0631\u0627\u062f\u06cc\u0648\u0627\u06a9\u062a\u06cc\u0648 \u0634\u06cc\u0631\u062f\u0647\u06cc \u0631\u0627 \u0645\u0648\u0642\u062a\u0627\u064b \u0645\u062a\u0648\u0642\u0641 \u0645\u06cc\u200c\u06a9\u0646\u062f.", "\u06af\u0627\u0644\u0627\u06a9\u062a\u0648\u0632\u0645\u06cc \u0646\u0648\u0632\u0627\u062f \u0645\u0646\u0639 \u0645\u0637\u0644\u0642 \u0634\u06cc\u0631\u062f\u0647\u06cc \u0645\u062d\u0633\u0648\u0628 \u0645\u06cc\u200c\u0634\u0648\u062f.", "\u062a\u0648\u0628\u0631\u06a9\u0644\u0648\u0632 \u0641\u0639\u0627\u0644 \u062a\u0627 \u0634\u0631\u0648\u0639 \u062f\u0631\u0645\u0627\u0646 \u0645\u0624\u062b\u0631\u060c \u0634\u06cc\u0631\u062f\u0647\u06cc \u0631\u0627 \u0645\u062d\u062f\u0648\u062f \u0645\u06cc\u200c\u06a9\u0646\u062f.", "\u0622\u0646\u062a\u06cc\u200c\u0698\u0646 \u0633\u0637\u062d\u06cc \u0647\u067e\u0627\u062a\u06cc\u062a B \u0628\u0647\u200c\u062a\u0646\u0647\u0627\u06cc\u06cc \u0645\u0627\u0646\u0639 \u0634\u06cc\u0631\u062f\u0647\u06cc \u0646\u06cc\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d."],
  },
  (28, 182): {
   "topic": "naegleRule",
   "lead": "\u0628\u0627 \u062a\u0627\u0631\u06cc\u062e LMP 20/4/93\u060c \u062a\u0627\u0631\u06cc\u062e \u062a\u062e\u0645\u06cc\u0646\u06cc \u0632\u0627\u06cc\u0645\u0627\u0646 = (3=4-1) \u0645\u0627\u0647 \u0648 (29=22+7) \u0631\u0648\u0632 \u21d2 93/12/29",
   "interpretation": "\u0637\u0628\u0642 \u0642\u0627\u0646\u0648\u0646 \u0646\u0627\u06cc\u06af\u0644\u060c \u0628\u0647 \u0627\u0648\u0644\u06cc\u0646 \u0631\u0648\u0632 \u0622\u062e\u0631\u06cc\u0646 \u0642\u0627\u0639\u062f\u06af\u06cc \u06f7 \u0631\u0648\u0632 \u0627\u0636\u0627\u0641\u0647 \u0648 \u06f9 \u0645\u0627\u0647 \u0628\u0647 \u0622\u0646 \u0627\u0641\u0632\u0648\u062f\u0647 \u0645\u06cc\u200c\u0634\u0648\u062f (\u06cc\u0627 \u06f3 \u0645\u0627\u0647 \u06a9\u0645 \u0645\u06cc\u200c\u0634\u0648\u062f)\u061b \u0628\u0627 \u0634\u0631\u0648\u0639 \u06f2\u06f0/\u06f4/\u06f9\u06f3: \u0631\u0648\u0632 \u06f2\u06f0+\u06f7=\u06f2\u06f7 \u0648 \u0645\u0627\u0647 \u06f4+\u06f9=\u06f1\u06f3 \u2192 \u0641\u0631\u0648\u0631\u062f\u06cc\u0646 \u0633\u0627\u0644 \u0628\u0639\u062f \u06cc\u0639\u0646\u06cc \u06f9\u06f4/\u06f1/\u06f2\u06f7. \u0628\u0646\u0627\u0628\u0631\u0627\u06cc\u0646 \u062a\u0627\u0631\u06cc\u062e \u062a\u062e\u0645\u06cc\u0646\u06cc \u0632\u0627\u06cc\u0645\u0627\u0646 \u06f9\u06f4/\u06f1/\u06f2\u06f7 \u0627\u0633\u062a.",
   "reasons": ["\u062a\u0627\u0631\u06cc\u062e 93/1/2 \u0642\u0627\u0639\u062f\u0647\u0654 \u0646\u0627\u06cc\u06af\u0644 \u0631\u0627 \u0628\u0647\u200c\u06a9\u0627\u0631 \u0646\u0645\u06cc\u200c\u0628\u0631\u062f.", "\u062a\u0627\u0631\u06cc\u062e 93/12/29 \u0645\u0639\u0627\u062f\u0644 \u0627\u0641\u0632\u0648\u062f\u0646 \u06f9 \u0645\u0627\u0647 \u0646\u06cc\u0633\u062a.", "27 \u0641\u0631\u0648\u0631\u062f\u06cc\u0646 94 \u0628\u0627 \u0642\u0627\u0646\u0648\u0646 \u0646\u0627\u06cc\u06af\u0644 \u062d\u0627\u0635\u0644 \u0645\u06cc\u200c\u0634\u0648\u062f\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u062a\u0627\u0631\u06cc\u062e 94/1/29 \u0645\u062d\u0627\u0633\u0628\u0647\u0654 \u0646\u0627\u062f\u0631\u0633\u062a \u0631\u0648\u0632 \u0627\u0633\u062a."],
  },
  (28, 183): {
   "topic": "pregnancyBleedingUS",
   "lead": "\u062f\u0631 \u062e\u0648\u0646\u200c\u0631\u06cc\u0632\u06cc \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0628\u062f\u0648\u0646 \u0627\u0646\u0642\u0628\u0627\u0636\u060c \u0627\u0648\u0644\u06cc\u0646 \u0627\u0642\u062f\u0627\u0645 \u062a\u0634\u062e\u06cc\u0635\u06cc \u0633\u0648\u0646\u0648\u06af\u0631\u0627\u0641\u06cc \u0627\u0633\u062a.",
   "interpretation": "\u0633\u0648\u0646\u0648\u06af\u0631\u0627\u0641\u06cc \u0628\u062f\u0648\u0646 \u062e\u0637\u0631 \u0628\u0648\u062f\u0647 \u0648 \u0645\u062d\u0644 \u062c\u0641\u062a\u060c \u0645\u06cc\u0632\u0627\u0646 \u0645\u0627\u06cc\u0639\u060c \u0628\u0642\u0627\u06cc \u062c\u0646\u06cc\u0646 \u0648 \u062f\u0644\u0627\u06cc\u0644 \u062e\u0648\u0646\u200c\u0631\u06cc\u0632\u06cc \u0631\u0627 \u0627\u0631\u0632\u06cc\u0627\u0628\u06cc \u0645\u06cc\u200c\u06a9\u0646\u062f\u061b \u0644\u0645\u0633 \u0648\u0627\u0698\u06cc\u0646\u0627\u0644 \u062f\u0631 \u062c\u0641\u062a \u0633\u0631\u0631\u0627\u0647\u06cc \u0627\u062d\u062a\u0645\u0627\u0644\u06cc \u0648 \u0642\u0628\u0644 \u0627\u0632 \u0633\u0648\u0646\u0648 \u0645\u0645\u0646\u0648\u0639 \u0627\u0633\u062a\u061b MRI/CT \u062e\u0637 \u0627\u0648\u0644 \u0646\u06cc\u0633\u062a\u0646\u062f.",
   "reasons": ["\u0644\u0645\u0633 \u0648\u0627\u0698\u06cc\u0646\u0627\u0644 \u062f\u0631 \u062c\u0641\u062a \u0633\u0631\u0631\u0627\u0647\u06cc \u0627\u062d\u062a\u0645\u0627\u0644\u06cc \u062e\u0637\u0631\u0646\u0627\u06a9 \u0627\u0633\u062a.", "\u0633\u0648\u0646\u0648\u06af\u0631\u0627\u0641\u06cc \u0631\u0648\u0634 \u0627\u0648\u0644\u06cc\u0647 \u0648 \u0628\u062f\u0648\u0646 \u062e\u0637\u0631 \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "MRI \u062f\u0631 \u062e\u0637 \u0627\u0648\u0644 \u062e\u0648\u0646\u200c\u0631\u06cc\u0632\u06cc \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0627\u0633\u062a\u0641\u0627\u062f\u0647 \u0646\u0645\u06cc\u200c\u0634\u0648\u062f.", "CT \u0628\u0647\u200c\u062e\u0627\u0637\u0631 \u067e\u0631\u062a\u0648\u062f\u0631\u0645\u0627\u0646\u06cc \u062f\u0631 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0645\u062d\u062f\u0648\u062f \u0645\u06cc\u200c\u0634\u0648\u062f."],
  },
  (28, 184): {
   "topic": "weightGainObese",
   "lead": "\u062f\u0631 BMI=40 (\u0686\u0627\u0642\u06cc \u062f\u0631\u062c\u0647\u0654 2)\u060c \u0627\u0641\u0632\u0627\u06cc\u0634 \u0648\u0632\u0646 \u062a\u0648\u0635\u06cc\u0647\u200c\u0634\u062f\u0647 \u062f\u0631 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc ~15 \u067e\u0648\u0646\u062f (5-9kg) \u0627\u0633\u062a.",
   "interpretation": "\u062a\u0648\u0635\u06cc\u0647\u0654 \u0645\u0624\u0633\u0633\u0647\u0654 \u067e\u0632\u0634\u06a9\u06cc \u0622\u0645\u0631\u06cc\u06a9\u0627 \u0628\u0631 \u0627\u0633\u0627\u0633 \u0634\u0627\u062e\u0635 \u062a\u0648\u062f\u0647\u0654 \u0628\u062f\u0646\u06cc \u0627\u0648\u0644\u06cc\u0647 \u0627\u0633\u062a: \u06a9\u0645\u200c\u0648\u0632\u0646 \u06f1\u06f2.\u06f5-\u06f1\u06f8 \u06a9\u06cc\u0644\u0648\u06af\u0631\u0645\u060c \u0646\u0631\u0645\u0627\u0644 \u06f1\u06f1.\u06f5-\u06f1\u06f6 \u06a9\u06cc\u0644\u0648\u06af\u0631\u0645\u060c \u0627\u0636\u0627\u0641\u0647\u200c\u0648\u0632\u0646 \u06f7-\u06f1\u06f1\u066b\u06f5 \u06a9\u06cc\u0644\u0648\u06af\u0631\u0645 \u0648 \u0686\u0627\u0642 (BMI \u2265 \u06f3\u06f0) \u06f5-\u06f9 \u06a9\u06cc\u0644\u0648\u06af\u0631\u0645 \u06cc\u0639\u0646\u06cc \u062f\u0631 \u0645\u062d\u062f\u0648\u062f\u0647\u0654 \u06f1\u06f1 \u062a\u0627 \u06f2\u06f0 \u067e\u0648\u0646\u062f \u0648 \u0645\u0639\u0645\u0648\u0644\u0627\u064b \u0647\u062f\u0641 \u0646\u0632\u062f\u06cc\u06a9 \u0628\u0647 \u06f1\u06f5 \u067e\u0648\u0646\u062f \u0628\u0631\u0627\u06cc \u0686\u0627\u0642\u06cc \u0645\u0641\u0631\u0637 \u0627\u0633\u062a\u061b \u06f2\u06f5 \u06cc\u0627 \u06f3\u06f5 \u0628\u06cc\u0634 \u0627\u0632 \u062d\u062f \u062a\u0648\u0635\u06cc\u0647 \u0627\u0633\u062a.",
   "reasons": ["\u06f3\u06f5 \u067e\u0648\u0646\u062f \u0628\u0631\u0627\u06cc \u0634\u0627\u062e\u0635 \u062a\u0648\u062f\u0647\u0654 \u0628\u062f\u0646\u06cc \u0646\u0631\u0645\u0627\u0644 \u062f\u0631 \u0646\u0638\u0631 \u06af\u0631\u0641\u062a\u0647 \u0645\u06cc\u200c\u0634\u0648\u062f.", "\u06f2\u06f5 \u067e\u0648\u0646\u062f \u0628\u0631\u0627\u06cc \u0627\u0636\u0627\u0641\u0647\u200c\u0648\u0632\u0646 (\u0646\u0647 \u0686\u0627\u0642\u06cc \u0645\u0641\u0631\u0637) \u0631\u0627\u06cc\u062c\u200c\u062a\u0631 \u0627\u0633\u062a.", "\u06f1\u06f5 \u067e\u0648\u0646\u062f \u0628\u0627 \u062a\u0648\u0635\u06cc\u0647\u0654 \u06af\u0631\u0648\u0647 \u0686\u0627\u0642 \u0647\u0645\u200c\u062e\u0648\u0627\u0646 \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u06f2\u06f0 \u067e\u0648\u0646\u062f \u062f\u0631 \u0628\u0627\u0644\u0627\u06cc \u062f\u0627\u0645\u0646\u0647\u0654 \u062a\u0648\u0635\u06cc\u0647 \u0628\u0631\u0627\u06cc \u0686\u0627\u0642\u06cc \u0645\u0641\u0631\u0637 \u0627\u0633\u062a."],
  },
  (28, 185): {
   "topic": "severePreeclampsiaLab",
   "lead": "\u067e\u0644\u0627\u06a9\u062a \u06f8\u06f9\u06f0\u06f0\u06f0 (<100000) \u0645\u0639\u06cc\u0627\u0631 \u067e\u0631\u0647\u200c\u0627\u06a9\u0644\u0627\u0645\u067e\u0633\u06cc \u0634\u062f\u06cc\u062f \u0627\u0633\u062a.",
   "interpretation": "\u0645\u0639\u06cc\u0627\u0631\u0647\u0627\u06cc \u067e\u0631\u0647\u200c\u0627\u06a9\u0644\u0627\u0645\u067e\u0633\u06cc \u0634\u062f\u06cc\u062f: \u0641\u0634\u0627\u0631 \u0628\u06cc\u0634 \u0627\u0632 \u06f1\u06f6\u06f0/\u06f1\u06f1\u06f0\u060c \u062a\u0631\u0648\u0645\u0628\u0648\u0633\u06cc\u062a\u0648\u067e\u0646\u06cc \u0632\u06cc\u0631 \u06f1\u06f0\u06f0 \u0647\u0632\u0627\u0631\u060c \u06a9\u0631\u0627\u062a\u06cc\u0646\u06cc\u0646 \u0628\u0627\u0644\u0627\u06cc \u06f1.\u06f1 \u06cc\u0627 \u062f\u0648 \u0628\u0631\u0627\u0628\u0631 \u0634\u062f\u0646\u060c \u0627\u0641\u0632\u0627\u06cc\u0634 \u062a\u0631\u0627\u0646\u0633\u200c\u0622\u0645\u06cc\u0646\u0627\u0632\u0647\u0627 \u0628\u0647 \u0628\u06cc\u0634 \u0627\u0632 \u062f\u0648 \u0628\u0631\u0627\u0628\u0631 \u062d\u062f \u0646\u0631\u0645\u0627\u0644\u060c \u0627\u062f\u0645 \u0631\u06cc\u0648\u06cc \u06cc\u0627 \u0639\u0644\u0627\u0626\u0645 \u0639\u0635\u0628\u06cc\u061b \u067e\u0631\u0648\u062a\u0626\u06cc\u0646\u0648\u0631\u06cc + \u0628\u0647\u200c\u062a\u0646\u0647\u0627\u06cc\u06cc \u0645\u0639\u06cc\u0627\u0631 \u0634\u062f\u06cc\u062f \u0646\u06cc\u0633\u062a\u061b \u06a9\u0631\u0627\u062a\u06cc\u0646\u06cc\u0646 \u06f0/\u06f7\u06f5 \u0648 \u0622\u0646\u0632\u06cc\u0645 \u0646\u0631\u0645\u0627\u0644 \u0645\u0639\u06cc\u0627\u0631 \u0646\u06cc\u0633\u062a\u0646\u062f.",
   "reasons": ["\u06a9\u0631\u0627\u062a\u06cc\u0646\u06cc\u0646 \u06f0/\u06f7\u06f5 \u0645\u06cc\u0644\u06cc\u200c\u06af\u0631\u0645 \u062f\u0631 \u0645\u062d\u062f\u0648\u062f\u0647\u0654 \u0637\u0628\u06cc\u0639\u06cc \u0627\u0633\u062a.", "\u067e\u0631\u0648\u062a\u0626\u06cc\u0646\u0648\u0631\u06cc + \u0628\u0647\u200c\u062a\u0646\u0647\u0627\u06cc\u06cc \u0645\u0639\u06cc\u0627\u0631 \u067e\u0631\u0647\u200c\u0627\u06a9\u0644\u0627\u0645\u067e\u0633\u06cc \u0634\u062f\u06cc\u062f \u0646\u06cc\u0633\u062a.", "\u0645\u0642\u062f\u0627\u0631 SGPT \u0628\u0631\u0627\u0628\u0631 \u06f2\u06f5 \u062f\u0631 \u0645\u062d\u062f\u0648\u062f\u0647\u0654 \u0637\u0628\u06cc\u0639\u06cc \u0642\u0631\u0627\u0631 \u062f\u0627\u0631\u062f.", "\u067e\u0644\u0627\u06a9\u062a \u0632\u06cc\u0631 \u06f1\u06f0\u06f0 \u0647\u0632\u0627\u0631 \u0645\u0639\u06cc\u0627\u0631 \u0627\u0635\u0644\u06cc \u067e\u0631\u0647\u200c\u0627\u06a9\u0644\u0627\u0645\u067e\u0633\u06cc \u0634\u062f\u06cc\u062f \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d."],
  },
}
